import React, { useState, useEffect, useRef } from 'react';
import { createConciergeChat } from '../services/geminiService';
import { Chat, GenerateContentResponse } from '@google/genai';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const ConciergeChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Welcome to Be the Light. I am King 2.0, your elite style consultant. How can I refine your look today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const chatRef = useRef<Chat | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!chatRef.current) {
      chatRef.current = createConciergeChat();
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping || !chatRef.current) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const result = await chatRef.current.sendMessageStream({ message: userMessage });
      let fullText = '';

      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text || '';
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1].text = fullText;
          return updated;
        });
      }
    } catch (error) {
      console.error('Chat error:', error);
      setMessages(prev => [...prev, { role: 'model', text: 'Apologies, Client. Connection to the throne is temporary unstable. One moment.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans">
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-slate-900 text-amber-500 w-16 h-16 rounded-full shadow-2xl flex items-center justify-center hover:scale-110 transition-transform active:scale-95 border border-amber-500/20"
          aria-label="Speak with King 2.0"
        >
          <span className="font-black text-xs">KING</span>
        </button>
      )}

      {isOpen && (
        <div className="bg-white/95 backdrop-blur-xl w-[350px] sm:w-[400px] h-[550px] rounded-[2.5rem] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.25)] border border-slate-100 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 duration-300">
          <div className="bg-slate-900 p-6 flex justify-between items-center">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-amber-500 rounded-xl flex items-center justify-center font-black text-slate-950">K2</div>
              <div>
                <h3 className="serif text-white font-bold leading-none">King 2.0</h3>
                <span className="text-[10px] text-amber-500 uppercase font-black tracking-widest">Style Consultant</span>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white transition-colors">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-4 scroll-smooth">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div 
                  className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                    msg.role === 'user' 
                    ? 'bg-slate-900 text-white rounded-tr-none' 
                    : 'bg-slate-50 text-slate-700 border border-slate-100 rounded-tl-none font-medium'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
          </div>

          <form onSubmit={handleSend} className="p-6 pt-0">
            <div className="relative">
              <input 
                type="text"
                placeholder="Ask King 2.0..."
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pl-5 pr-14 text-sm font-medium focus:bg-white transition-all outline-none ring-2 ring-transparent focus:ring-amber-500/20"
                value={input}
                onChange={e => setInput(e.target.value)}
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-slate-900 text-amber-500 px-4 rounded-xl hover:bg-amber-500 hover:text-slate-950 transition-all"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default ConciergeChat;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product, CartItem, User, AuthState, Category, Lookbook } from '../types';
import { INITIAL_PRODUCTS, LOOKBOOKS } from '../constants';
import { supabase } from '../services/supabase';

interface AppContextType {
  products: Product[];
  lookbooks: Lookbook[];
  cart: CartItem[];
  auth: AuthState;
  loading: boolean;
  addToCart: (product: Product, quantity: number) => void;
  addBundleToCart: (lookbook: Lookbook) => void;
  removeFromCart: (productId: string) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  login: (email: string, pass: string) => boolean;
  logout: () => void;
  signup: (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => Promise<boolean>;
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  addLookbook: (lb: Omit<Lookbook, 'id'>) => Promise<void>;
  updateLookbook: (lb: Lookbook) => Promise<void>;
  deleteLookbook: (id: string) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [lookbooks, setLookbooks] = useState<Lookbook[]>(LOOKBOOKS);
  const [loading, setLoading] = useState(false);

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('btl_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('btl_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const fetchData = async () => {
    if (supabase.supabaseUrl.includes('placeholder-project')) return;

    setLoading(true);
    try {
      const { data: pData } = await supabase.from('products').select('*').order('createdAt', { ascending: false });
      if (pData && pData.length > 0) setProducts(pData);

      const { data: lbData } = await supabase.from('lookbooks').select('*').order('created_at', { ascending: false });
      if (lbData && lbData.length > 0) {
        setLookbooks(lbData.map((item: any) => ({
          id: item.id,
          title: item.title,
          description: item.description,
          price: item.price,
          imageUrl: item.image_url,
          productIds: item.product_ids || []
        })));
      }
    } catch (e) {
      console.warn("Supabase fetch failed, continuing with dummy data:", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('btl_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('btl_auth', JSON.stringify(auth));
  }, [auth]);

  const addToCart = (product: Product, quantity: number) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        const newQty = Math.min(existing.quantity + quantity, product.stock);
        return prev.map(item => item.id === product.id ? { ...item, quantity: newQty } : item);
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const addBundleToCart = (lookbook: Lookbook) => {
    const bundleProducts = products.filter(p => lookbook.productIds.includes(p.id) && p.stock > 0);
    if (bundleProducts.length === 0) {
      alert("Items in this look are currently out of stock.");
      return;
    }

    setCart(prev => {
      let newCart = [...prev];
      bundleProducts.forEach(product => {
        const existing = newCart.find(item => item.id === product.id);
        if (existing) {
          existing.quantity = Math.min(existing.quantity + 1, product.stock);
        } else {
          newCart.push({ ...product, quantity: 1, selectedSize: 'L' });
        }
      });
      return newCart;
    });
    alert(`Acquisition complete. Items added to selection.`);
  };

  const addProduct = async (p: Omit<Product, 'id' | 'createdAt'>) => {
    const newProduct = { ...p, id: Date.now().toString(), createdAt: Date.now() };
    setProducts(prev => [newProduct as Product, ...prev]);

    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      try {
        await supabase.from('products').insert([p]);
      } catch (e) {
        console.error("Supabase Save Error:", e);
      }
    }
  };

  const updateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      try {
        await supabase.from('products').update(p).eq('id', p.id);
      } catch (e) {
        console.error("Supabase Update Error:", e);
      }
    }
  };

  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      await supabase.from('products').delete().eq('id', id);
    }
  };

  const addLookbook = async (lb: Omit<Lookbook, 'id'>) => {
    const newLb = { ...lb, id: Date.now().toString() };
    setLookbooks(prev => [newLb as Lookbook, ...prev]);

    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      try {
        const payload = {
          title: lb.title,
          description: lb.description,
          price: lb.price,
          image_url: lb.imageUrl,
          product_ids: lb.productIds
        };
        await supabase.from('lookbooks').insert([payload]);
      } catch (e) {
        console.error("Supabase Save Error:", e);
      }
    }
  };

  const updateLookbook = async (lb: Lookbook) => {
    setLookbooks(prev => prev.map(item => item.id === lb.id ? lb : item));
    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      try {
        const payload = {
          title: lb.title,
          description: lb.description,
          price: lb.price,
          image_url: lb.imageUrl,
          product_ids: lb.productIds
        };
        await supabase.from('lookbooks').update(payload).eq('id', lb.id);
      } catch (e) {
        console.error("Supabase Update Error:", e);
      }
    }
  };

  const deleteLookbook = async (id: string) => {
    setLookbooks(prev => prev.filter(lb => lb.id !== id));
    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      await supabase.from('lookbooks').delete().eq('id', id);
    }
  };

  const signup = async (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => {
    const userId = Date.now().toString();
    setAuth({ user: { id: userId, email, isAdmin: false, name, phone, location, isWhatsApp }, isAuthenticated: true });

    if (!supabase.supabaseUrl.includes('placeholder-project')) {
      try {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password: pass,
          options: { data: { full_name: name, phone, location, is_whatsapp: isWhatsApp } }
        });
        if (authError) throw authError;
        if (authData.user) {
          await supabase.from('profiles').insert([{ id: authData.user.id, full_name: name, phone, location, is_whatsapp: isWhatsApp }]);
        }
      } catch (e: any) {
        console.warn("Supabase Signup skipped or failed:", e.message);
      }
    }
    return true;
  };

  const login = (email: string, pass: string) => {
    if (email === 'admin@bethelight.com' && pass === 'admin123') {
      setAuth({ user: { id: 'admin-0', email, isAdmin: true, name: 'Admin Store' }, isAuthenticated: true });
      return true;
    }
    setAuth({ user: { id: 'user-0', email, isAdmin: false, name: 'Valued Client' }, isAuthenticated: true });
    return true;
  };

  const logout = () => setAuth({ user: null, isAuthenticated: false });
  const removeFromCart = (id: string) => setCart(prev => prev.filter(i => i.id !== id));
  const updateCartQuantity = (id: string, q: number) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: q } : i));
  const clearCart = () => setCart([]);

  return (
    <AppContext.Provider value={{
      products, lookbooks, cart, auth, loading, addToCart, addBundleToCart, removeFromCart, updateCartQuantity, clearCart,
      login, logout, signup, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, Category, User, Lookbook } from '../types';
import { getMentorAdvice } from '../services/geminiService';
import { supabase } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'inventory' | 'lookbooks' | 'broadcast'>('inventory');
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [mentorQuery, setMentorQuery] = useState('');
  const [mentorResponse, setMentorResponse] = useState('');
  const [loadingAi, setLoadingAi] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [broadcastMessage, setBroadcastMessage] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');
  const [customers, setCustomers] = useState<User[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lookbook Form State
  const [lbData, setLbData] = useState({
    title: '',
    description: '',
    price: 0,
    imageUrl: '',
    productIds: [] as string[]
  });

  // Product Form State
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    stock: 0,
    category: CATEGORIES[0],
    imageUrl: ''
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    const { data } = await supabase.from('profiles').select('*');
    if (data) {
      setCustomers(data.map((p: any) => ({
        id: p.id,
        name: p.full_name,
        email: 'Client Record',
        isAdmin: false,
        phone: p.phone,
        isWhatsApp: p.is_whatsapp,
        status: 'New'
      })));
    }
  };

  if (!auth.user?.isAdmin) return null;

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      await updateProduct({ ...formData, id: editingId, createdAt: Date.now() });
    } else {
      await addProduct(formData);
    }
    resetForm();
  };

  const handleEditProduct = (p: Product) => {
    setEditingId(p.id);
    setFormData({
      name: p.name,
      description: p.description,
      price: p.price,
      stock: p.stock,
      category: p.category,
      imageUrl: p.imageUrl
    });
    setIsAdding(true);
    setActiveTab('inventory');
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (lbData.productIds.length === 0) {
      alert("Please link at least one product to this look.");
      return;
    }
    if (editingId) {
      await updateLookbook({ ...lbData, id: editingId });
    } else {
      await addLookbook(lbData);
    }
    resetForm();
  };

  const handleEditLookbook = (lb: Lookbook) => {
    setEditingId(lb.id);
    setLbData({
      title: lb.title,
      description: lb.description,
      price: lb.price,
      imageUrl: lb.imageUrl,
      productIds: lb.productIds
    });
    setIsAdding(true);
    setActiveTab('lookbooks');
  };

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setFormData({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLbData({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadingImage(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/\s/g, '_')}`;
      const { data, error } = await supabase.storage
        .from('product-images')
        .upload(`media/${fileName}`, file);

      if (error) throw error;

      const { data: { publicUrl } } = supabase.storage
        .from('product-images')
        .getPublicUrl(`media/${fileName}`);

      if (activeTab === 'inventory') {
        setFormData(prev => ({ ...prev, imageUrl: publicUrl }));
      } else {
        setLbData(prev => ({ ...prev, imageUrl: publicUrl }));
      }
    } catch (error: any) {
      alert(`Upload failed: ${error.message}. Ensure the 'product-images' bucket exists and is public.`);
    } finally {
      setUploadingImage(false);
    }
  };

  const toggleLookbookProduct = (id: string) => {
    setLbData(prev => ({
      ...prev,
      productIds: prev.productIds.includes(id) 
        ? prev.productIds.filter(pid => pid !== id)
        : [...prev.productIds, id]
    }));
  };

  const handleBroadcast = (customer: User) => {
    if (!customer.phone) {
      alert("Customer has no number registered.");
      return;
    }
    const message = `*BE THE LIGHT BOUTIQUE*\n\nHi ${customer.name}!\n\n${broadcastMessage}\n\nShop now: ${window.location.origin}/#/shop`;
    const url = `https://wa.me/${customer.phone.replace(/\+/g, '')}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f1f4f6]">
