import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';

const LOGO_URL = "https://npigysjyukxhloemfvva.supabase.co/storage/v1/object/public/product-images/products/logo.jpg";

const Navbar: React.FC = () => {
  const { cart, auth, logout } = useApp();
  const [isOpen, setIsOpen] = useState(false);
  const navigate = useNavigate();

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center">
          <Link to="/" className="flex-shrink-0 flex items-center space-x-3 group">
            <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center overflow-hidden border border-slate-200 group-hover:scale-110 transition-transform shadow-sm">
              <img 
                src={LOGO_URL} 
                alt="Be the Light Logo" 
                className="w-full h-full object-cover"
              />
            </div>
            <span className="serif text-xl md:text-2xl font-bold tracking-tighter text-slate-900 group-hover:text-amber-500 transition-colors">BE THE LIGHT</span>
          </Link>

          {/* Desktop Links */}
          <div className="hidden md:flex items-center space-x-8">
            <Link to="/" className="text-[10px] font-black uppercase tracking-[0.2em] hover:text-amber-500 transition-colors">Home</Link>
            <Link to="/shop" className="text-[10px] font-black uppercase tracking-[0.2em] hover:text-amber-500 transition-colors">Shop</Link>
            <Link to="/lookbooks" className="text-[10px] font-black uppercase tracking-[0.2em] hover:text-amber-500 transition-colors">Lookbooks</Link>
            {auth.user?.isAdmin && (
              <Link to="/admin" className="text-[10px] font-black uppercase tracking-[0.2em] text-amber-600 border border-amber-600 px-4 py-2 rounded-full hover:bg-amber-600 hover:text-white transition-all">Atelier</Link>
            )}
          </div>

          <div className="flex items-center space-x-5">
            <Link to="/cart" className="relative p-2 text-slate-700 hover:text-amber-500 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              {cartCount > 0 && (
                <span className="absolute top-0 right-0 inline-flex items-center justify-center px-2 py-1 text-[8px] font-black leading-none text-white transform translate-x-1/2 -translate-y-1/2 bg-amber-500 rounded-full">
                  {cartCount}
                </span>
              )}
            </Link>

            {auth.isAuthenticated ? (
              <div className="hidden md:flex items-center space-x-4">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hi, {auth.user?.name?.split(' ')[0]}</span>
                <button onClick={logout} className="text-[10px] font-black uppercase tracking-widest text-red-500 hover:text-red-600">Logout</button>
              </div>
            ) : (
              <Link to="/login" className="text-[10px] font-black uppercase tracking-widest text-amber-600 hover:text-amber-700">Client Login</Link>
            )}

            {/* Mobile menu button */}
            <button onClick={() => setIsOpen(!isOpen)} className="md:hidden p-2 text-slate-700">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} />
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-slate-100 p-6 space-y-6 animate-in slide-in-from-top-4">
          <Link to="/" onClick={() => setIsOpen(false)} className="block text-xs font-black uppercase tracking-widest">Home</Link>
          <Link to="/shop" onClick={() => setIsOpen(false)} className="block text-xs font-black uppercase tracking-widest">Shop</Link>
          <Link to="/lookbooks" onClick={() => setIsOpen(false)} className="block text-xs font-black uppercase tracking-widest">Lookbooks</Link>
          {auth.user?.isAdmin && (
            <Link to="/admin" onClick={() => setIsOpen(false)} className="block text-xs font-black uppercase tracking-widest text-amber-600">Atelier Control</Link>
          )}
          <div className="pt-6 border-t border-slate-100">
            {auth.isAuthenticated ? (
              <button onClick={() => { logout(); setIsOpen(false); }} className="block w-full text-left text-xs font-black uppercase tracking-widest text-red-500">Logout</button>
            ) : (
              <Link to="/login" onClick={() => setIsOpen(false)} className="block text-xs font-black uppercase tracking-widest text-amber-600">Client Login</Link>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { CURRENCY, PAYMENT_DETAILS, WHATSAPP_NUMBER } from '../constants';
import { useNavigate } from 'react-router-dom';

const Checkout: React.FC = () => {
  const { cart, auth } = useApp();
  const navigate = useNavigate();
  const [deliveryMode, setDeliveryMode] = useState<'delivery' | 'pickup'>('delivery');
  const [deliveryPoint, setDeliveryPoint] = useState('');

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const generateWhatsAppUrl = () => {
    const userName = auth.user?.name || 'Valued Client';
    const orderDetails = cart.map(item => `• ${item.name} (Size: ${item.selectedSize || 'N/A'}, ${item.quantity}x) - ${CURRENCY} ${item.price * item.quantity}`).join('\n');
    const deliveryStr = deliveryMode === 'delivery' ? `Standard Delivery to: ${deliveryPoint || 'Not Specified'}` : 'Store Pickup (Aflao Branch)';

    const message = `*BE THE LIGHT - NEW ORDER REQUEST*\n\n` +
      `*Client:* ${userName}\n` +
      `*Fulfillment:* ${deliveryStr}\n\n` +
      `*Order Selection:*\n${orderDetails}\n\n` +
      `*Total Investment:* ${CURRENCY} ${total.toLocaleString()}\n\n` +
      `--------------------------\n` +
      `*PAYMENT STATUS*\n` +
      `I have initiated the payment of ${CURRENCY} ${total.toLocaleString()} via Mobile Money. Please find the confirmation details below/attached.\n\n` +
      `*Note:* Please process my order for ${deliveryMode === 'delivery' ? 'dispatch' : 'pickup'}.`;

    const encoded = encodeURIComponent(message);
    return `https://wa.me/${WHATSAPP_NUMBER.replace(/\+/g, '')}?text=${encoded}`;
  };

  const handleComplete = () => {
    if (deliveryMode === 'delivery' && !deliveryPoint.trim()) {
      alert("Please specify your exact delivery point (e.g., Denu Police Station).");
      return;
    }
    window.open(generateWhatsAppUrl(), '_blank');
  };

  if (cart.length === 0) {
    return (
       <div className="max-w-7xl mx-auto px-4 py-24 text-center">
        <h1 className="text-3xl font-black mb-4 uppercase tracking-tighter">Your selection is empty</h1>
        <button onClick={() => navigate('/shop')} className="text-amber-500 font-black uppercase tracking-widest text-[10px]">Return to Catalog</button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-20">
      <div className="bg-white border border-slate-100 rounded-[3rem] p-10 md:p-16 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.08)]">
        <div className="text-center mb-16">
          <div className="inline-flex items-center justify-center w-24 h-24 bg-amber-50 rounded-[2.5rem] mb-8">
            <svg className="w-12 h-12 text-amber-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
          </div>
          <h1 className="text-4xl font-black text-slate-900 mb-4 tracking-tighter uppercase">Finalize Selection</h1>
          <p className="text-slate-500 font-medium">Greetings, {auth.user?.name?.split(' ')[0] || 'Boss'}. Verify your items below.</p>
        </div>

        {/* Fulfillment Method */}
        <div className="mb-16">
          <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-8 ml-2">Fulfillment Mode</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
            <button 
              onClick={() => setDeliveryMode('delivery')}
              className={`p-8 rounded-[2rem] border-2 text-left transition-all ${deliveryMode === 'delivery' ? 'border-amber-500 bg-amber-50/30 ring-4 ring-amber-500/10' : 'border-slate-50 bg-white hover:border-slate-200'}`}
            >
              <h4 className="font-black text-lg text-slate-900">Standard Delivery</h4>
              <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">2-4 Hour Service</p>
            </button>

            <button 
              onClick={() => setDeliveryMode('pickup')}
              className={`p-8 rounded-[2rem] border-2 text-left transition-all ${deliveryMode === 'pickup' ? 'border-amber-500 bg-amber-50/30 ring-4 ring-amber-500/10' : 'border-slate-50 bg-white hover:border-slate-200'}`}
            >
              <h4 className="font-black text-lg text-slate-900">Store Pickup</h4>
              <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">Aflao Boutique</p>
            </button>
          </div>

          {deliveryMode === 'delivery' && (
            <div className="animate-in fade-in slide-in-from-top-4 duration-500">
               <label className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-4 block ml-2">Exact Delivery Point</label>
               <input 
                 required
                 type="text" 
                 placeholder="e.g., Denu Police Station / Opposite Winners Chapel"
                 className="w-full bg-slate-50 border-2 border-slate-100 p-6 rounded-2xl font-bold focus:bg-white focus:border-amber-500 transition-all outline-none"
                 value={deliveryPoint}
                 onChange={(e) => setDeliveryPoint(e.target.value)}
               />
               <p className="mt-4 text-[10px] text-amber-600 font-black uppercase tracking-widest ml-2 italic">*Required for dispatch</p>
            </div>
          )}
        </div>

        {/* Payment Summary */}
        <div className="bg-slate-900 rounded-[2.5rem] p-10 mb-16 text-white">
          <div className="flex justify-between items-end mb-8">
            <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500">Order Investment</h3>
            <span className="text-amber-500 font-black text-2xl">{CURRENCY} {total.toLocaleString()}</span>
          </div>

          <div className="space-y-4">
            <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 block mb-1">Mobile Money (MTN)</span>
               <p className="font-bold text-lg">{PAYMENT_DETAILS.mtn}</p>
            </div>
          </div>
        </div>

        {/* Action Button */}
        <button 
          onClick={handleComplete}
          className="w-full bg-slate-950 text-white py-8 rounded-3xl font-black text-sm uppercase tracking-[0.3em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-2xl flex items-center justify-center space-x-4 active:scale-[0.98]"
        >
          <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
          <span>Send Order via WhatsApp</span>
        </button>
      </div>
    </div>
  );
};

