                         value={lookbookForm.title} onChange={e => setLookbookForm({...lookbookForm, title: e.target.value})} />
                       <input required type="number" placeholder="Bundle Price" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-amber-500 outline-none"
                         value={lookbookForm.price} onChange={e => setLookbookForm({...lookbookForm, price: parseFloat(e.target.value)})} />
                       <textarea required placeholder="Description" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-amber-500 outline-none"
                         value={lookbookForm.description} onChange={e => setLookbookForm({...lookbookForm, description: e.target.value})} />
                       <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Cover Image</label>
                          <input type="file" onChange={e => handleImageUpload(e, 'lookbook')} className="text-sm text-slate-500"/>
                       </div>
                       <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Include Products (Ctrl+Click)</label>
                          <select multiple className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm h-32"
                             value={lookbookForm.productIds} 
                             onChange={e => setLookbookForm({...lookbookForm, productIds: Array.from(e.target.selectedOptions, o => o.value)})}>
                             {products.map(p => <option key={p.id} value={p.id}>{p.name} - {CURRENCY}{p.price}</option>)}
                          </select>
                       </div>
                    </div>
                    <div className="flex space-x-4">
                      <button type="submit" disabled={uploading} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold text-sm">Save Collection</button>
                      <button type="button" onClick={closeForm} className="bg-white border border-slate-200 text-slate-500 px-6 py-3 rounded-xl font-bold text-sm">Cancel</button>
                    </div>
                 </form>
              ) : (
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                   {lookbooks.map(lb => (
                     <div key={lb.id} className="border border-slate-100 rounded-2xl overflow-hidden group">
                        <div className="aspect-video bg-slate-100 relative">
                           <img src={lb.imageUrl} className="w-full h-full object-cover" />
                           <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity space-x-4">
                              <button onClick={() => { setEditId(lb.id); setLookbookForm({...lb, productIds: lb.productIds || []}); setIsEditing(true); }} className="bg-white text-slate-900 px-3 py-1 rounded text-xs font-bold">EDIT</button>
                              <button onClick={() => deleteLookbook(lb.id)} className="bg-red-500 text-white px-3 py-1 rounded text-xs font-bold">DELETE</button>
                           </div>
                        </div>
                        <div className="p-4">
                           <h4 className="font-bold text-slate-900">{lb.title}</h4>
                           <p className="text-xs text-slate-500 mt-1">{lb.productIds.length} Items Included</p>
                        </div>
                     </div>
                   ))}
                </div>
              )}
            </div>
          )}

          {/* BROADCAST VIEW */}
          {activeView === 'broadcast' && (
            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 md:p-8">
               <h3 className="font-bold text-lg text-slate-800 mb-6">WhatsApp Broadcast Center</h3>

               <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 mb-8">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Message Content</label>
                  <textarea 
                    className="w-full p-4 bg-white border border-slate-200 rounded-xl text-base text-slate-700 focus:ring-2 focus:ring-green-500 outline-none"
                    rows={4}
                    value={broadcastMsg}
                    onChange={e => setBroadcastMsg(e.target.value)}
                  />
                  <div className="mt-4 flex flex-col sm:flex-row justify-end">
                     <button onClick={() => {
                        if (confirm(`Send to ${customers.filter(c => c.phone).length} clients?`)) {
                          customers.forEach((c, i) => setTimeout(() => sendBroadcast(c.phone), i * 1500));
                        }
                     }} className="bg-green-500 text-white px-6 py-3 rounded-xl font-bold text-sm hover:bg-green-600 transition-all shadow-lg shadow-green-500/30 w-full sm:w-auto">
                        Broadcast to All ({customers.length})
                     </button>
                  </div>
               </div>

               <div>
                 <h4 className="font-bold text-sm text-slate-700 mb-4 uppercase tracking-widest">Individual Targeting</h4>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {customers.map(c => (
                      <div key={c.id} className="flex items-center justify-between p-4 border border-slate-100 rounded-xl hover:border-green-500 transition-colors bg-white">
                         <div>
                            <div className="font-bold text-sm text-slate-900 truncate max-w-[150px]">{c.name}</div>
                            <div className="text-xs text-slate-400">{c.phone}</div>
                         </div>
                         <button onClick={() => sendBroadcast(c.phone)} className="text-green-500 hover:bg-green-50 p-2 rounded-lg">
                           <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.246 2.248 3.484 5.232 3.481 8.413-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.305 1.654zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.438 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-2.652-.001-5.146 1.03-7.023 2.906-1.877 1.877-2.912 4.367-2.914 7.02-.002 2.123.594 3.72 1.589 5.395l-1.01 3.689 3.759-.986z"/></svg>
                         </button>
                      </div>
                    ))}
                 </div>
               </div>
            </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { CURRENCY, PAYMENT_DETAILS, WHATSAPP_NUMBER } from '../constants';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../services/supabase';

const Checkout: React.FC = () => {
  const { cart, auth, clearCart } = useApp();
  const navigate = useNavigate();
  const [deliveryMode, setDeliveryMode] = useState<'delivery' | 'pickup'>('delivery');
  const [deliveryPoint, setDeliveryPoint] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const saveOrderToDatabase = async () => {
    if (!auth.user || !auth.user.id) return;

    try {
      const { error } = await supabase.from('orders').insert([
        {
          user_id: auth.user.id,
          items: cart,
          total_amount: total,
          delivery_mode: deliveryMode,
          delivery_point: deliveryPoint || 'Store Pickup',
          status: 'pending'
        }
      ]);

      if (error) throw error;
    } catch (err) {
      console.error("Order logging failed:", err);
      // We continue to WhatsApp even if DB logging fails to not block the sale
    }
  };

  const handleComplete = async () => {
    if (deliveryMode === 'delivery' && !deliveryPoint.trim()) {
      alert("Please specify your exact delivery point (e.g., Denu Police Station).");
      return;
    }

    setIsProcessing(true);

    // 1. Generate WhatsApp Link
    const userName = auth.user?.name || 'Valued Client';
    const orderDetails = cart.map(item => `• ${item.name} (Size: ${item.selectedSize || 'N/A'}, ${item.quantity}x) - ${CURRENCY} ${item.price * item.quantity}`).join('\n');
    const deliveryStr = deliveryMode === 'delivery' ? `Standard Delivery to: ${deliveryPoint || 'Not Specified'}` : 'Store Pickup (Aflao Branch)';

    const message = `*BE THE LIGHT - NEW ORDER REQUEST*\n\n` +
      `*Client:* ${userName}\n` +
      `*Fulfillment:* ${deliveryStr}\n\n` +
      `*Order Selection:*\n${orderDetails}\n\n` +
      `*Total Investment:* ${CURRENCY} ${total.toLocaleString()}\n\n` +
      `--------------------------\n` +
      `*PAYMENT STATUS*\n` +
      `I have initiated the payment of ${CURRENCY} ${total.toLocaleString()} via Mobile Money. Please find the confirmation details below/attached.\n\n` +
      `*Note:* Please process my order for ${deliveryMode === 'delivery' ? 'dispatch' : 'pickup'}.`;

    const encoded = encodeURIComponent(message);
    const waUrl = `https://wa.me/${WHATSAPP_NUMBER.replace(/\+/g, '')}?text=${encoded}`;

    // 2. Save to DB (Background)
    if (auth.isAuthenticated) {
      await saveOrderToDatabase();
    }

    // 3. Clear Cart and Redirect
    clearCart();
    window.open(waUrl, '_blank');
    navigate('/');
    setIsProcessing(false);
  };

  if (cart.length === 0) {
    return (
       <div className="max-w-7xl mx-auto px-4 py-24 text-center">
        <h1 className="text-3xl font-black mb-4 uppercase tracking-tighter">Your selection is empty</h1>
        <button onClick={() => navigate('/shop')} className="text-amber-500 font-black uppercase tracking-widest text-[10px]">Return to Catalog</button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-20">
      <div className="bg-white border border-slate-100 rounded-[3rem] p-10 md:p-16 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.08)]">
        <div className="text-center mb-16">
          <div className="inline-flex items-center justify-center w-24 h-24 bg-amber-50 rounded-[2.5rem] mb-8">
            <svg className="w-12 h-12 text-amber-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
          </div>
          <h1 className="text-4xl font-black text-slate-900 mb-4 tracking-tighter uppercase">Finalize Selection</h1>
          <p className="text-slate-500 font-medium">Greetings, {auth.user?.name?.split(' ')[0] || 'Boss'}. Verify your items below.</p>
        </div>

        {/* Fulfillment Method */}
        <div className="mb-16">
          <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-8 ml-2">Fulfillment Mode</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
            <button 
              onClick={() => setDeliveryMode('delivery')}
              className={`p-8 rounded-[2rem] border-2 text-left transition-all ${deliveryMode === 'delivery' ? 'border-amber-500 bg-amber-50/30 ring-4 ring-amber-500/10' : 'border-slate-50 bg-white hover:border-slate-200'}`}
            >
              <h4 className="font-black text-lg text-slate-900">Standard Delivery</h4>
              <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">2-4 Hour Service</p>
            </button>

            <button 
              onClick={() => setDeliveryMode('pickup')}
              className={`p-8 rounded-[2rem] border-2 text-left transition-all ${deliveryMode === 'pickup' ? 'border-amber-500 bg-amber-50/30 ring-4 ring-amber-500/10' : 'border-slate-50 bg-white hover:border-slate-200'}`}
            >
              <h4 className="font-black text-lg text-slate-900">Store Pickup</h4>
              <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">Aflao Boutique</p>
            </button>
          </div>

          {deliveryMode === 'delivery' && (
            <div className="animate-in fade-in slide-in-from-top-4 duration-500">
               <label className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-4 block ml-2">Exact Delivery Point</label>
               <input 
                 required
                 type="text" 
                 placeholder="e.g., Denu Police Station / Opposite Winners Chapel"
                 className="w-full bg-slate-50 border-2 border-slate-100 p-6 rounded-2xl font-bold focus:bg-white focus:border-amber-500 transition-all outline-none"
                 value={deliveryPoint}
                 onChange={(e) => setDeliveryPoint(e.target.value)}
               />
               <p className="mt-4 text-[10px] text-amber-600 font-black uppercase tracking-widest ml-2 italic">*Required for dispatch</p>
            </div>
          )}
        </div>

        {/* Payment Summary */}
        <div className="bg-slate-900 rounded-[2.5rem] p-10 mb-16 text-white">
          <div className="flex justify-between items-end mb-8">
            <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500">Order Investment</h3>
            <span className="text-amber-500 font-black text-2xl">{CURRENCY} {total.toLocaleString()}</span>
          </div>

          <div className="space-y-4">
            <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 block mb-1">Mobile Money (MTN)</span>
               <p className="font-bold text-lg">{PAYMENT_DETAILS.mtn}</p>
            </div>
          </div>
        </div>

        {/* Action Button */}
        <button 
          onClick={handleComplete}
          disabled={isProcessing}
          className="w-full bg-slate-950 text-white py-8 rounded-3xl font-black text-sm uppercase tracking-[0.3em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-2xl flex items-center justify-center space-x-4 active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
        >
          {isProcessing ? (
             <span>Processing Order...</span>
          ) : (
            <>
              <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
              <span>Send Order via WhatsApp</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default Checkout;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, Category, User, Lookbook } from '../types';
import { supabase } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  // State
  const [activeView, setActiveView] = useState<'dashboard' | 'inventory' | 'lookbooks' | 'broadcast'>('dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(false); // Default closed on mobile

  // Form State
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [productForm, setProductForm] = useState({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
  const [lookbookForm, setLookbookForm] = useState({ title: '', description: '', price: 0, imageUrl: '', productIds: [] as string[] });
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    // Fetch profiles and map to User type, mocking financial data for demo if null
    const { data } = await supabase.from('profiles').select('*');
    if (data) {
      setCustomers(data.map((p: any) => ({
        id: p.id,
        name: p.full_name || 'Anonymous',
        email: 'client@example.com', // Placeholder if email not in public profile
        isAdmin: false,
        phone: p.phone,
        isWhatsApp: p.is_whatsapp,
        location: p.location,
        totalSpent: Math.floor(Math.random() * 5000), // Mock data since we don't have orders table yet
        orderCount: Math.floor(Math.random() * 20),   // Mock data since we don't have orders table yet
        status: 'Regular'
      })).sort((a, b) => (b.totalSpent || 0) - (a.totalSpent || 0)));
    }
  };

  const handleDownloadReport = () => {
    const headers = ['Client Name', 'Phone', 'Location', 'Total Spent', 'Orders Count', 'Status'];
    const rows = customers.map(c => [
      c.name || 'N/A',
      c.phone || 'N/A',
      c.location || 'N/A',
      `${c.totalSpent || 0}`,
      `${c.orderCount || 0}`,
      c.status || 'New'
    ]);

    const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `BTL_Sales_Report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/\s/g, '_')}`;
      const { error } = await supabase.storage.from('product-images').upload(`media/${fileName}`, file);
      if (error) throw error;
      const { data: { publicUrl } } = supabase.storage.from('product-images').getPublicUrl(`media/${fileName}`);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));
    } catch (err: any) {
      alert('Upload failed: ' + err.message);
    } finally {
      setUploading(false);
    }
  };

  const saveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    else await addProduct(productForm);
    closeForm();
  };

  const saveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    closeForm();
  };

  const closeForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const sendBroadcast = (phone?: string) => {
    if (!phone) return;
    const url = `https://wa.me/${phone.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
    window.open(url, '_blank');
  };

  const stats = {
    revenue: customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0),
    products: products.length,
    clients: customers.length,
    lowStock: products.filter(p => p.stock < 5).length
  };

  if (!auth.user?.isAdmin) return null;

  return (
    <div className="fixed inset-0 z-[100] flex bg-[#f1f4f6] font-sans text-slate-800 overflow-hidden">
      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden backdrop-blur-sm"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`bg-white w-64 flex-shrink-0 border-r border-slate-200 flex flex-col transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 fixed inset-y-0 left-0 z-30 lg:static`}>
        <div className="h-16 flex items-center justify-between px-6 border-b border-slate-100">
          <span className="font-black text-xl tracking-tighter text-slate-900">ARCHITECT<span className="text-amber-500">.</span></span>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <nav className="px-3 space-y-1">
            {[
              { id: 'dashboard', label: 'Dashboard', icon: 'M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z' },
              { id: 'inventory', label: 'Inventory', icon: 'M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4' },
              { id: 'lookbooks', label: 'Lookbooks', icon: 'M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z' },
              { id: 'broadcast', label: 'Broadcast', icon: 'M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z' },
            ].map((item) => (
              <button
