import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, Category, User, Lookbook } from '../types';
import { supabase } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  // State
  const [activeView, setActiveView] = useState<'dashboard' | 'inventory' | 'lookbooks' | 'broadcast'>('dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(false); // Default closed on mobile

  // Form State
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [productForm, setProductForm] = useState({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
  const [lookbookForm, setLookbookForm] = useState({ title: '', description: '', price: 0, imageUrl: '', productIds: [] as string[] });
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    // Fetch profiles and map to User type
    const { data } = await supabase.from('profiles').select('*');
    if (data) {
      setCustomers(data.map((p: any) => ({
        id: p.id,
        name: p.full_name || 'Anonymous',
        email: 'client@example.com', // Placeholder if email not in public profile
        isAdmin: false,
        phone: p.phone,
        isWhatsApp: p.is_whatsapp,
        location: p.location,
        // Use real DB values if they exist (from the SQL update), otherwise fallback to mock
        totalSpent: p.total_spent !== undefined ? p.total_spent : Math.floor(Math.random() * 5000), 
        orderCount: p.orders_count !== undefined ? p.orders_count : Math.floor(Math.random() * 20),
        status: 'Regular' as const // Fix: Explicitly cast string to literal type
      })).sort((a, b) => (b.totalSpent || 0) - (a.totalSpent || 0)));
    }
  };

  const handleDownloadReport = () => {
    const headers = ['Client Name', 'Phone', 'Location', 'Total Spent', 'Orders Count', 'Status'];
    const rows = customers.map(c => [
      c.name || 'N/A',
      c.phone || 'N/A',
      c.location || 'N/A',
      `${c.totalSpent || 0}`,
      `${c.orderCount || 0}`,
      c.status || 'New'
    ]);

    const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `BTL_Sales_Report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/\s/g, '_')}`;
      const { error } = await supabase.storage.from('product-images').upload(`media/${fileName}`, file);
      if (error) throw error;
      const { data: { publicUrl } } = supabase.storage.from('product-images').getPublicUrl(`media/${fileName}`);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));
    } catch (err: any) {
      alert('Upload failed: ' + err.message);
    } finally {
      setUploading(false);
    }
  };

  const saveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    else await addProduct(productForm);
    closeForm();
  };

  const saveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    closeForm();
  };

  const closeForm = () => {
