/// <reference types="vite/client" />
import { createClient } from '@supabase/supabase-js';

// Access environment variables directly. 
// Vite replaces process.env.VITE_SUPABASE_URL if defined in vite.config.ts, 
// but import.meta.env is the standard way.
// We use a safe fallback chain.

const getVar = (key: string) => {
  // We cannot use dynamic access like process.env[key] because Vite's 'define' plugin
  // relies on static string replacement (e.g. process.env.MY_VAR -> "value").
  // Dynamic access fails at runtime if the process object doesn't exist.

  if (key === 'VITE_SUPABASE_URL') {
    return import.meta.env.VITE_SUPABASE_URL || (typeof process !== 'undefined' && process.env?.VITE_SUPABASE_URL);
  }
  if (key === 'VITE_SUPABASE_ANON_KEY') {
    return import.meta.env.VITE_SUPABASE_ANON_KEY || (typeof process !== 'undefined' && process.env?.VITE_SUPABASE_ANON_KEY);
  }
  return '';
};

const rawUrl = getVar('VITE_SUPABASE_URL')?.toString().trim();
const rawKey = getVar('VITE_SUPABASE_ANON_KEY')?.toString().trim();

const isValidUrl = (url?: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key?: string) => key && key.length > 20 && !key.includes('placeholder');

// Debugging logs for the browser console
if (!isValidUrl(rawUrl)) console.error("Supabase Error: VITE_SUPABASE_URL is missing or invalid. Current value:", rawUrl);
if (!isValidKey(rawKey)) console.error("Supabase Error: VITE_SUPABASE_ANON_KEY is missing or invalid.");

const supabaseUrl = isValidUrl(rawUrl) ? rawUrl! : 'https://placeholder.supabase.co';
const supabaseAnonKey = isValidKey(rawKey) ? rawKey! : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid_placeholder';

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

