/// <reference types="vite/client" />
import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product, CartItem, User, AuthState, Category, Lookbook } from '../types';
import { supabase } from '../services/supabase';

// Safely detect if we should use dummy mode (fallback)
const envUrl = import.meta.env.VITE_SUPABASE_URL || "";
const isSupabaseDummy = !envUrl || envUrl.includes('placeholder-project');

interface AppContextType {
  products: Product[];
  lookbooks: Lookbook[];
  cart: CartItem[];
  auth: AuthState;
  loading: boolean;
  addToCart: (product: Product, quantity: number) => void;
  addBundleToCart: (lookbook: Lookbook) => void;
  removeFromCart: (productId: string) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  login: (email: string, pass: string) => boolean;
  logout: () => void;
  signup: (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => Promise<boolean>;
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  addLookbook: (lb: Omit<Lookbook, 'id'>) => Promise<void>;
  updateLookbook: (lb: Lookbook) => Promise<void>;
  deleteLookbook: (id: string) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [lookbooks, setLookbooks] = useState<Lookbook[]>([]);
  const [loading, setLoading] = useState(false);

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('btl_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('btl_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const fetchData = async () => {
    if (isSupabaseDummy) {
      console.warn("Maison Core: Operating in Local Fallback mode (No Database Connected).");
      return;
    }

    setLoading(true);
    try {
      const { data: pData, error: pError } = await supabase.from('products').select('*').order('createdAt', { ascending: false });
      if (pError) throw pError;
      if (pData) setProducts(pData);

      const { data: lbData, error: lbError } = await supabase.from('lookbooks').select('*').order('created_at', { ascending: false });
      if (lbError) throw lbError;
      if (lbData) {
        setLookbooks(lbData.map((item: any) => ({
          id: item.id,
          title: item.title,
          description: item.description,
          price: item.price,
          imageUrl: item.image_url,
          productIds: item.product_ids || []
        })));
      }
    } catch (e) {
      console.error("Supabase fetch failed:", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem('btl_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('btl_auth', JSON.stringify(auth));
  }, [auth]);

  const addToCart = (product: Product, quantity: number) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        const newQty = Math.min(existing.quantity + quantity, product.stock);
        return prev.map(item => item.id === product.id ? { ...item, quantity: newQty } : item);
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const addBundleToCart = (lookbook: Lookbook) => {
    const bundleProducts = products.filter(p => lookbook.productIds.includes(p.id) && p.stock > 0);
    if (bundleProducts.length === 0) {
      alert("Items in this look are currently out of stock.");
      return;
    }

    setCart(prev => {
      let newCart = [...prev];
      bundleProducts.forEach(product => {
        const existing = newCart.find(item => item.id === product.id);
        if (existing) {
          existing.quantity = Math.min(existing.quantity + 1, product.stock);
        } else {
          newCart.push({ ...product, quantity: 1, selectedSize: 'L' });
        }
      });
      return newCart;
    });
    alert(`Acquisition complete. Items added to selection.`);
  };

  const addProduct = async (p: Omit<Product, 'id' | 'createdAt'>) => {
    if (!isSupabaseDummy) {
      try {
        const { data, error } = await supabase.from('products').insert([p]).select();
        if (error) throw error;
        if (data) {
           setProducts(prev => [data[0] as Product, ...prev]);
        }
      } catch (e) {
        console.error("Supabase Save Error:", e);
        alert("Failed to save product to database.");
      }
    }
  };

  const updateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    if (!isSupabaseDummy) {
      try {
        await supabase.from('products').update(p).eq('id', p.id);
      } catch (e) {
        console.error("Supabase Update Error:", e);
      }
    }
  };

  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    if (!isSupabaseDummy) {
      await supabase.from('products').delete().eq('id', id);
    }
  };

  const addLookbook = async (lb: Omit<Lookbook, 'id'>) => {
    if (!isSupabaseDummy) {
      try {
        const payload = {
          title: lb.title,
          description: lb.description,
          price: lb.price,
          image_url: lb.imageUrl,
          product_ids: lb.productIds
        };
        const { data, error } = await supabase.from('lookbooks').insert([payload]).select();
        if (error) throw error;
        if (data) {
          const newLb = {
             id: data[0].id,
             title: data[0].title,
             description: data[0].description,
             price: data[0].price,
             imageUrl: data[0].image_url,
             productIds: data[0].product_ids || []
          };
          setLookbooks(prev => [newLb, ...prev]);
        }
      } catch (e) {
        console.error("Supabase Save Error:", e);
      }
    }
  };

  const updateLookbook = async (lb: Lookbook) => {
    setLookbooks(prev => prev.map(item => item.id === lb.id ? lb : item));
    if (!isSupabaseDummy) {
      try {
        const payload = {
          title: lb.title,
          description: lb.description,
          price: lb.price,
          image_url: lb.imageUrl,
          product_ids: lb.productIds
        };
        await supabase.from('lookbooks').update(payload).eq('id', lb.id);
      } catch (e) {
        console.error("Supabase Update Error:", e);
      }
    }
  };

  const deleteLookbook = async (id: string) => {
    setLookbooks(prev => prev.filter(lb => lb.id !== id));
    if (!isSupabaseDummy) {
      await supabase.from('lookbooks').delete().eq('id', id);
    }
  };

  const signup = async (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => {
    if (!isSupabaseDummy) {
      try {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password: pass,
          options: { data: { full_name: name, phone, location, is_whatsapp: isWhatsApp } }
        });
        if (authError) throw authError;
        if (authData.user) {
          const { error: profileError } = await supabase.from('profiles').insert([{ id: authData.user.id, full_name: name, phone, location, is_whatsapp: isWhatsApp }]);
          if (profileError) throw profileError;

          setAuth({ user: { id: authData.user.id, email, isAdmin: false, name, phone, location, isWhatsApp }, isAuthenticated: true });
          return true;
        }
      } catch (e: any) {
        console.error("Supabase Signup Failed:", e.message);
        alert(`Signup Failed: ${e.message}`);
        return false;
      }
    }
    return false;
  };

  const login = (email: string, pass: string) => {
    if (email === 'admin@bethelight.com' && pass === 'admin123') {
      setAuth({ user: { id: 'admin-0', email, isAdmin: true, name: 'Admin Store' }, isAuthenticated: true });
      return true;
    }
    setAuth({ user: { id: 'user-0', email, isAdmin: false, name: 'Valued Client' }, isAuthenticated: true });
    return true;
  };

  const logout = () => setAuth({ user: null, isAuthenticated: false });
  const removeFromCart = (id: string) => setCart(prev => prev.filter(i => i.id !== id));
  const updateCartQuantity = (id: string, q: number) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: q } : i));
  const clearCart = () => setCart([]);

  return (
    <AppContext.Provider value={{
      products, lookbooks, cart, auth, loading, addToCart, addBundleToCart, removeFromCart, updateCartQuantity, clearCart,
      login, logout, signup, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

