import { createClient } from '@supabase/supabase-js';

// Use process.env variables as polyfilled by the vite.config.ts define block.
// This avoids TS errors related to ImportMeta and failing vite/client references.
const supabaseUrl = process.env.VITE_SUPABASE_URL || "";
const supabaseAnonKey = process.env.VITE_SUPABASE_ANON_KEY || "";

const isValidUrl = (url: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key: string) => key && key.length > 20 && !key.includes('placeholder');

// Runtime verification for the developer
if (!isValidUrl(supabaseUrl)) {
  console.error("Supabase Configuration Error: VITE_SUPABASE_URL is missing or invalid. Check your .env file.");
}
if (!isValidKey(supabaseAnonKey)) {
  console.error("Supabase Configuration Error: VITE_SUPABASE_ANON_KEY is missing or invalid. Check your .env file.");
}

// Fallback to placeholders to prevent the app from crashing entirely, 
// though functionality requiring the database will fail.
const finalUrl = isValidUrl(supabaseUrl) ? supabaseUrl : 'https://placeholder.supabase.co';
const finalKey = isValidKey(supabaseAnonKey) ? supabaseAnonKey : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid_placeholder';

export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

