              <button onClick={() => customers.forEach(c => sendBroadcast(c.phone))} className="bg-green-500 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-green-200">Broadcast to All Clients</button>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

