      setUploading(false);
    }
  };

  const handleProductSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) {
      await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    } else {
      await addProduct(productForm);
    }
    resetForm();
  };

  const handleLookbookSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) {
      await updateLookbook({ ...lookbookForm, id: editId });
    } else {
      await addLookbook(lookbookForm);
    }
    resetForm();
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const startEditProduct = (p: Product) => {
    setProductForm({ name: p.name, description: p.description, price: p.price, stock: p.stock, category: p.category, imageUrl: p.imageUrl });
    setEditId(p.id);
    setIsEditing(true);
  };

  const startEditLookbook = (l: Lookbook) => {
    setLookbookForm({ title: l.title, description: l.description, price: l.price, imageUrl: l.imageUrl, productIds: l.productIds });
    setEditId(l.id);
    setIsEditing(true);
  };

