          {isEditing ? (
            <div className="bg-white border border-slate-100 rounded-[2rem] p-8 shadow-xl">
              <form onSubmit={handleProductSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <input required placeholder="Product Name" className="w-full p-4 bg-slate-50 rounded-xl border-none font-bold" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} />
                  <textarea required placeholder="Description" rows={4} className="w-full p-4 bg-slate-50 rounded-xl border-none font-medium" value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} />
