                      </div>
                    ) : (
                      <div className="space-y-2">
                        <p className="text-xs font-bold text-slate-400 uppercase">Product Visual</p>
                        <input type="file" onChange={e => handleImageUpload(e, 'product')} className="text-xs" disabled={uploading} />
