                    <div className="flex gap-3">
                      <button onClick={() => startEditProduct(p)} className="text-[10px] font-black uppercase text-slate-900 hover:text-amber-500">Edit</button>
                      <button onClick={() => deleteProduct(p.id)} className="text-[10px] font-black uppercase text-red-500 hover:text-red-700">Delete</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {activeTab === 'lookbooks' && (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
            <h2 className="text-2xl font-black uppercase tracking-tight">Runway Exhibits ({lookbooks.length})</h2>
            <button onClick={() => setIsEditing(true)} className="bg-amber-500 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest">
              + New Curation
            </button>
          </div>

          {isEditing ? (
            <div className="bg-white border border-slate-100 rounded-[2rem] p-8 shadow-xl">
