                          <input 
                            type="checkbox" 
                            checked={lookbookForm.productIds.includes(p.id)}
                            onChange={(e) => {
                              const ids = e.target.checked 
                                ? [...lookbookForm.productIds, p.id] 
                                : lookbookForm.productIds.filter(id => id !== p.id);
                              setLookbookForm({...lookbookForm, productIds: ids});
                            }}
                          />
                          <span>{p.name}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                  <div className="border-2 border-dashed border-slate-200 rounded-xl p-4 text-center">
                    {lookbookForm.imageUrl ? (
                      <img src={lookbookForm.imageUrl} className="h-24 mx-auto rounded-lg object-cover" />
                    ) : (
                      <input type="file" onChange={e => handleImageUpload(e, 'lookbook')} className="text-[10px]" disabled={uploading} />
                    )}
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="submit" className="flex-1 bg-slate-900 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest">Publish Look</button>
                    <button type="button" onClick={resetForm} className="flex-1 border border-slate-200 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest text-slate-400">Cancel</button>
                  </div>
                </div>
              </form>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {lookbooks.map(lb => (
                <div key={lb.id} className="group relative aspect-square rounded-[3rem] overflow-hidden shadow-lg">
                  <img src={lb.imageUrl} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-8 text-center text-white">
                    <h3 className="text-xl font-black mb-2 uppercase">{lb.title}</h3>
                    <p className="text-xs font-bold text-amber-500 mb-6">{lb.productIds.length} Linked Items</p>
                    <div className="flex gap-4">
                      <button onClick={() => startEditLookbook(lb)} className="text-[10px] font-black uppercase bg-white text-slate-900 px-4 py-2 rounded-full">Edit</button>
                      <button onClick={() => deleteLookbook(lb.id)} className="text-[10px] font-black uppercase bg-red-500 text-white px-4 py-2 rounded-full">Delete</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {activeTab === 'customers' && (
        <div className="bg-white border border-slate-100 rounded-[2.5rem] overflow-hidden shadow-sm">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
              <tr>
                <th className="px-8 py-6">Client</th>
                <th className="px-8 py-6">Phone</th>
                <th className="px-8 py-6">Location</th>
                <th className="px-8 py-6">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {customers.map(c => (
                <tr key={c.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-8 py-6">
                    <p className="font-black text-slate-900">{c.name}</p>
                    <p className="text-xs text-slate-400 font-medium lowercase tracking-tighter">{c.email}</p>
                  </td>
                  <td className="px-8 py-6 font-bold text-slate-600">{c.phone || 'N/A'}</td>
                  <td className="px-8 py-6 font-bold text-slate-500">{c.location || 'Aflao'}</td>
                  <td className="px-8 py-6">
                    <span className="bg-amber-50 text-amber-600 text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-widest border border-amber-100">Regular</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

