                activeView === view ? 'bg-amber-50 text-amber-600' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span className="capitalize">{view}</span>
            </button>
          ))}

          <div className="pt-8 pb-4">
            <span className="px-4 text-[10px] font-black uppercase tracking-widest text-slate-300">Admin Actions</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-3 px-4 py-3 rounded-xl text-sm font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
