              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {[
                  { label: 'Total Revenue', value: `${CURRENCY} ${totalRevenue}`, color: 'bg-emerald-50', iconColor: 'text-emerald-500', icon: '$' },
                  { label: 'Products', value: products.length, color: 'bg-blue-50', iconColor: 'text-blue-500', icon: '📦' },
