                        ) : (
                          <div className="space-y-2">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Upload Visual</p>
                            <input type="file" onChange={e => handleImageUpload(e, 'product')} className="text-xs" disabled={uploading} />
                          </div>
                        )}
                      </div>
                      <div className="flex gap-4">
                        <button type="submit" className="flex-1 bg-slate-900 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest">{editId ? 'UPDATE' : 'SAVE'}</button>
                        <button type="button" onClick={resetForm} className="flex-1 border border-slate-200 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest text-slate-400 bg-white">CANCEL</button>
                      </div>
                    </div>
                  </form>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-8 py-4">Product</th>
                        <th className="px-8 py-4">Price</th>
                        <th className="px-8 py-4">Stock</th>
                        <th className="px-8 py-4">Category</th>
                        <th className="px-8 py-4">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {products.map(p => (
                        <tr key={p.id} className="hover:bg-slate-50/30 transition-colors">
                          <td className="px-8 py-4 flex items-center space-x-3">
                            <img src={p.imageUrl} className="w-10 h-10 rounded-lg object-cover" />
                            <span className="font-bold text-slate-900">{p.name}</span>
                          </td>
                          <td className="px-8 py-4 font-bold">{CURRENCY} {p.price.toLocaleString()}</td>
                          <td className="px-8 py-4">
                            <span className={`px-3 py-1 rounded-full text-[10px] font-black ${p.stock < 5 ? 'bg-red-50 text-red-500 border border-red-100' : 'bg-emerald-50 text-emerald-500 border border-emerald-100'}`}>
                              {p.stock} Units
                            </span>
                          </td>
                          <td className="px-8 py-4 text-slate-500 text-xs font-bold">{p.category}</td>
                          <td className="px-8 py-4 space-x-4">
                            <button onClick={() => { setEditId(p.id); setProductForm(p); setIsEditing(true); }} className="text-[10px] font-black uppercase text-amber-600">Edit</button>
                            <button onClick={() => deleteProduct(p.id)} className="text-[10px] font-black uppercase text-red-400">Delete</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {activeView === 'Lookbooks' && (
            <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                <h3 className="serif text-xl font-bold text-slate-900">Runway Collections</h3>
                {!isEditing && <button onClick={() => setIsEditing(true)} className="bg-amber-500 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest">+ NEW</button>}
              </div>

              <div className="p-10">
                {isEditing ? (
                  <form onSubmit={handleSaveLookbook} className="max-w-2xl space-y-6">
                    <input required placeholder="Collection Title" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold" value={lookbookForm.title} onChange={e => setLookbookForm({...lookbookForm, title: e.target.value})} />
                    <input required type="number" placeholder="0" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold" value={lookbookForm.price || ''} onChange={e => setLookbookForm({...lookbookForm, price: parseFloat(e.target.value)})} />
                    <textarea required placeholder="Description" rows={4} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl font-medium" value={lookbookForm.description} onChange={e => setLookbookForm({...lookbookForm, description: e.target.value})} />

                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Cover Image</p>
                      <input type="file" onChange={e => handleImageUpload(e, 'lookbook')} className="text-xs" disabled={uploading} />
                    </div>

                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Include Products (CTRL+CLICK)</p>
                      <select multiple className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl h-48 font-bold" value={lookbookForm.productIds} onChange={e => setLookbookForm({...lookbookForm, productIds: Array.from(e.target.selectedOptions, o => o.value)})}>
                        {products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                      </select>
                    </div>

                    <div className="flex gap-4 pt-4">
                      <button type="submit" className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest">Save Collection</button>
                      <button type="button" onClick={resetForm} className="border border-slate-200 px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-400">Cancel</button>
                    </div>
                  </form>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {lookbooks.map(lb => (
                      <div key={lb.id} className="relative aspect-square rounded-[2rem] overflow-hidden group shadow-md">
                        <img src={lb.imageUrl} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-8 text-center">
                          <h4 className="text-white font-black text-xl mb-2 uppercase">{lb.title}</h4>
                          <p className="text-amber-500 font-bold text-xs mb-6">{lb.productIds.length} Linked Items</p>
                          <div className="flex space-x-3">
                            <button onClick={() => { setEditId(lb.id); setLookbookForm(lb); setIsEditing(true); }} className="text-[8px] font-black uppercase tracking-widest bg-white text-slate-900 px-4 py-2 rounded-full">Edit</button>
                            <button onClick={() => deleteLookbook(lb.id)} className="text-[8px] font-black uppercase tracking-widest bg-red-500 text-white px-4 py-2 rounded-full">Delete</button>
                          </div>
                        </div>
                      </div>
                    ))}
                    {lookbooks.length === 0 && <p className="col-span-full text-center py-20 text-slate-300 font-bold uppercase tracking-widest text-xs">No runway exhibits found</p>}
                  </div>
                )}
              </div>
            </div>
          )}

          {activeView === 'Broadcast' && (
            <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
              <div className="p-8 border-b border-slate-50">
                <h3 className="serif text-xl font-bold text-slate-900">WhatsApp Broadcast Center</h3>
              </div>
              <div className="p-10">
                <div className="max-w-4xl bg-slate-50/50 p-10 rounded-[2.5rem] border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Message Content</p>
                  <textarea 
                    className="w-full p-8 border border-slate-100 rounded-[2rem] h-48 font-medium text-slate-600 focus:bg-white transition-all shadow-inner"
                    value={broadcastMsg}
                    onChange={e => setBroadcastMsg(e.target.value)}
                  />
                  <div className="mt-8 flex justify-end">
                    <button 
                      onClick={() => {
                        customers.forEach(c => {
                          if (c.phone) {
                            const url = `https://wa.me/${c.phone.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                            window.open(url, '_blank');
                          }
                        });
                      }}
                      className="bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-100 hover:scale-105 active:scale-95 transition-all"
                    >
                      Broadcast to All ({customers.length})
                    </button>
                  </div>
                </div>

                <div className="mt-12">
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Individual Targeting</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {customers.map(c => (
                        <div key={c.id} className="bg-white p-6 rounded-2xl border border-slate-100 flex justify-between items-center shadow-sm">
                          <div>
                            <p className="font-bold text-slate-900">{c.name}</p>
                            <p className="text-xs text-slate-400">{c.phone || 'No Phone'}</p>
                          </div>
                          <button 
                            disabled={!c.phone}
                            onClick={() => {
                              const url = `https://wa.me/${c.phone!.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                              window.open(url, '_blank');
                            }}
                            className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                          >
                            →
                          </button>
                        </div>
                      ))}
                   </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Floating KING button from screenshot */}
      <button className="fixed bottom-10 right-10 w-16 h-16 bg-slate-950 text-amber-500 rounded-full shadow-2xl flex items-center justify-center border-4 border-slate-800 font-black text-[10px] tracking-tighter z-[101]">
        KING
      </button>
    </div>
  );
};

export default AdminDashboard;

import { Category, Product, Lookbook } from './types';

export const CATEGORIES: Category[] = ['Shirts', 'Shoes', 'Easy Wear', 'Trousers', 'Caps'];

export const CURRENCY = 'GHC';
export const WHATSAPP_NUMBER = '+233243961325'; 
export const PAYMENT_DETAILS = {
  mtn: '0544543156 (BE THE LIGHT COLLECTION/ PRECIOUS KING ZANU)',
  telecel: 'Payment via MTN Recommended',
  bank: 'Contact Concierge for Bank Details'
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/\s/g, '_')}`;
      const { error } = await supabase.storage.from('product-images').upload(`public/${fileName}`, file);
      if (error) throw error;
      const { data: { publicUrl } } = supabase.storage.from('product-images').getPublicUrl(`public/${fileName}`);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));
    } catch (err: any) {
      alert('Upload failed: ' + err.message);
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    else await addProduct(productForm);
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const lowStockCount = products.filter(p => p.stock < 5).length;
  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);

  return (
    <div className="fixed inset-0 flex bg-[#f1f4f6] font-sans text-slate-800">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-100 flex flex-col h-full shrink-0">
        <div className="h-20 flex items-center px-8 border-b border-slate-50">
          <span className="font-black text-xl tracking-tighter text-slate-900 uppercase">ARCHITECT<span className="text-amber-500">.</span></span>
        </div>

        <nav className="flex-grow py-8 px-4 space-y-2">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button
              key={view}
              onClick={() => { setActiveView(view as any); setIsEditing(false); }}
              className={`w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold transition-all ${
                activeView === view ? 'bg-amber-50 text-amber-600' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span className="capitalize">{view}</span>
            </button>
          ))}

          <div className="pt-8 pb-4">
            <span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Admin Actions</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
          </button>
        </nav>
      </aside>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col min-w-0 overflow-hidden">
        {/* Top Header */}
        <header className="h-20 bg-white border-b border-slate-50 flex items-center justify-between px-10 shrink-0">
          <h1 className="serif text-2xl font-bold text-slate-800">{activeView}</h1>
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-3 bg-slate-50 px-4 py-2 rounded-full border border-slate-100">
              <div className="w-8 h-8 bg-slate-900 rounded-full flex items-center justify-center text-white font-black text-xs">A</div>
              <span className="text-xs font-black uppercase tracking-widest text-slate-900">Admin</span>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-grow overflow-y-auto p-10 space-y-10">
          {activeView === 'Dashboard' && (
            <>
              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {[
                  { label: 'Total Revenue', value: `${CURRENCY} ${totalRevenue}`, color: 'bg-emerald-50', iconColor: 'text-emerald-500', icon: 'GHC' },
                  { label: 'Products', value: products.length, color: 'bg-blue-50', iconColor: 'text-blue-500', icon: '📦' },
                  { label: 'Loyal Clients', value: customers.length, color: 'bg-purple-50', iconColor: 'text-purple-500', icon: '👥' },
                  { label: 'Low Stock', value: lowStockCount, color: 'bg-red-50', iconColor: 'text-red-500', icon: '⚠️' },
                ].map((stat, i) => (
                  <div key={i} className="bg-white p-7 rounded-2xl border border-slate-100 flex justify-between items-center shadow-sm">
                    <div>
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">{stat.label}</p>
                      <p className="text-2xl font-bold text-slate-900">{stat.value}</p>
                    </div>
                    <div className={`w-12 h-12 ${stat.color} ${stat.iconColor} rounded-xl flex items-center justify-center text-sm font-bold`}>
                       {stat.icon}
                    </div>
                  </div>
                ))}
              </div>

              {/* Clients Table */}
              <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                  <h3 className="serif text-xl font-bold text-slate-900">Most Loyal Clients</h3>
                  <button className="bg-slate-900 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest">Generate Sale Report (CSV)</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-8 py-5">Client</th>
                        <th className="px-8 py-5">Total Spent</th>
                        <th className="px-8 py-5">Orders</th>
                        <th className="px-8 py-5">Location</th>
                        <th className="px-8 py-5">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {customers.map(c => (
                        <tr key={c.id} className="hover:bg-slate-50/30 transition-colors">
                          <td className="px-8 py-6 font-bold text-slate-900">{c.name}</td>
                          <td className="px-8 py-6">{CURRENCY} {c.totalSpent?.toLocaleString()}</td>
                          <td className="px-8 py-6">{c.orderCount}</td>
                          <td className="px-8 py-6 text-slate-500">{c.location}</td>
                          <td className="px-8 py-6">
                            <span className="text-[8px] font-black uppercase tracking-widest text-amber-600 bg-amber-50 px-3 py-1 rounded-full border border-amber-100">
                               {c.totalSpent && c.totalSpent > 1000 ? 'VIP' : 'Regular'}
                            </span>
                          </td>
                        </tr>
                      ))}
                      {customers.length === 0 && (
                        <tr><td colSpan={5} className="px-8 py-20 text-center text-slate-300 font-bold uppercase tracking-widest text-xs">No client data available</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          )}

          {activeView === 'Inventory' && (
            <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                <h3 className="serif text-xl font-bold text-slate-900">Product Management</h3>
                <button onClick={() => setIsEditing(true)} className="bg-amber-500 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-900 transition-all">+ NEW</button>
              </div>

              {isEditing ? (
                <div className="p-10 bg-slate-50/50">
                  <form onSubmit={handleSaveProduct} className="max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-6">
                      <input required placeholder="Product Name" className="w-full p-4 bg-white border border-slate-100 rounded-xl font-bold" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} />
                      <textarea required placeholder="Description" rows={4} className="w-full p-4 bg-white border border-slate-100 rounded-xl font-medium" value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} />
                      <div className="grid grid-cols-2 gap-4">
                        <input required type="number" placeholder="Price" className="w-full p-4 bg-white border border-slate-100 rounded-xl font-bold" value={productForm.price || ''} onChange={e => setProductForm({...productForm, price: parseFloat(e.target.value)})} />
                        <input required type="number" placeholder="Stock" className="w-full p-4 bg-white border border-slate-100 rounded-xl font-bold" value={productForm.stock || ''} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div className="space-y-6">
                      <select className="w-full p-4 bg-white border border-slate-100 rounded-xl font-bold" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value as any})}>
                        {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                      <div className="border-2 border-dashed border-slate-200 rounded-xl p-8 text-center bg-white">
                        {productForm.imageUrl ? (
                          <div className="relative group">
                            <img src={productForm.imageUrl} className="h-32 mx-auto rounded-lg object-cover" />
                            <button type="button" onClick={() => setProductForm({...productForm, imageUrl: ''})} className="absolute -top-2 -right-2 bg-red-500 text-white w-6 h-6 rounded-full flex items-center justify-center">×</button>
                          </div>
                        ) : (
                          <div className="space-y-2">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Upload Visual</p>
                            <input type="file" onChange={e => handleImageUpload(e, 'product')} className="text-xs" disabled={uploading} />
                          </div>
                        )}
                      </div>
                      <div className="flex gap-4">
                        <button type="submit" className="flex-1 bg-slate-900 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest">{editId ? 'UPDATE' : 'SAVE'}</button>
                        <button type="button" onClick={resetForm} className="flex-1 border border-slate-200 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest text-slate-400 bg-white">CANCEL</button>
                      </div>
                    </div>
                  </form>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                      <tr>
                        <th className="px-8 py-5">Product</th>
                        <th className="px-8 py-5">Price</th>
                        <th className="px-8 py-5">Stock</th>
                        <th className="px-8 py-5">Category</th>
                        <th className="px-8 py-5">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {products.map(p => (
                        <tr key={p.id} className="hover:bg-slate-50/30 transition-colors text-sm">
                          <td className="px-8 py-4 flex items-center space-x-4">
                            <img src={p.imageUrl} className="w-10 h-10 rounded-lg object-cover bg-slate-100" />
                            <span className="font-bold text-slate-900">{p.name}</span>
                          </td>
