                <div className="mt-12">
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Individual Targeting</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {customers.map(c => (
                        <div key={c.id} className="bg-white p-6 rounded-2xl border border-slate-100 flex justify-between items-center shadow-sm">
