};

export default AdminDashboard;

import { createClient } from '@supabase/supabase-js';

const getEnv = (key: string): string => {
  // @ts-ignore
  const viteEnv = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env[key] : undefined;
  // @ts-ignore
  const procEnv = typeof process !== 'undefined' && process.env ? process.env[key] : undefined;
  // @ts-ignore
  const windowEnv = typeof window !== 'undefined' && (window as any)._env_ ? (window as any)._env_[key] : undefined;

  return viteEnv || procEnv || windowEnv || "";
};

const supabaseUrl = getEnv('SUPABASE_DATABASE_URL');
const supabaseAnonKey = getEnv('SUPABASE_ANON_KEY');

const isValidUrl = (url: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key: string) => key && key.length > 20 && !key.includes('placeholder');

if (!isValidUrl(supabaseUrl)) {
  console.warn("Supabase Config: SUPABASE_DATABASE_URL is missing or invalid. Check your environment variables.");
} else {
  console.log("Supabase Config: URL detected successfully.");
}

const finalUrl = isValidUrl(supabaseUrl) ? supabaseUrl : 'https://placeholder-project.supabase.co';
const finalKey = isValidKey(supabaseAnonKey) ? supabaseAnonKey : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid';

export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);

    try {
      // Use a clean filename and a standard folder structure
      const timestamp = Date.now();
      const cleanFileName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
      const filePath = `products/${timestamp}_${cleanFileName}`;

      const { data, error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: true,
          contentType: file.type // Explicitly setting the content type helps with CORS/Fetch issues
        });

      if (uploadError) {
        console.error("Supabase Upload Error details:", uploadError);
        throw uploadError;
      }

      const { data: { publicUrl } } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));

    } catch (err: any) {
      console.error("Upload process caught error:", err);
      // If "Failed to fetch" occurs, it's almost certainly a CORS issue in Supabase Dashboard
      const msg = err.message === 'Failed to fetch' 
        ? 'Network Error (Failed to fetch). Please ensure CORS is enabled for this domain in your Supabase Storage settings.' 
        : err.message;
      alert('Upload failed: ' + msg);
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    else await addProduct(productForm);
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const lowStockCount = products.filter(p => p.stock < 5).length;
  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);

