          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-3 bg-slate-50 px-4 py-2 rounded-full border border-slate-100">
              <div className="w-8 h-8 bg-slate-900 rounded-full flex items-center justify-center text-white font-black text-xs">A</div>
              <span className="text-xs font-black uppercase tracking-widest text-slate-900">Admin</span>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-grow overflow-y-auto p-10 space-y-10">
          {activeView === 'Dashboard' && (
            <>
              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
