            </button>
          ))}

          <div className="pt-8 pb-4">
            <span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Admin Actions</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
          </button>
        </nav>
      </aside>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col min-w-0 overflow-hidden">
        {/* Top Header */}
        <header className="h-20 bg-white border-b border-slate-50 flex items-center justify-between px-10 shrink-0">
          <h1 className="serif text-2xl font-bold text-slate-800">{activeView}</h1>
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-3 bg-slate-50 px-4 py-2 rounded-full border border-slate-100">
              <div className="w-8 h-8 bg-slate-900 rounded-full flex items-center justify-center text-white font-black text-xs">A</div>
