const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || "";

const isValidUrl = (url: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key: string) => key && key.length > 20 && !key.includes('placeholder');

if (!isValidUrl(supabaseUrl)) {
  console.error("CRITICAL: SUPABASE_DATABASE_URL is missing or invalid. Check your environment variables and vite.config.ts mappings.");
} else {
  console.log(`Supabase initialized for: ${supabaseUrl.substring(0, 15)}...`);
}

// Fallback to placeholder to prevent total crash, but initialization log will show failure
const finalUrl = isValidUrl(supabaseUrl) ? supabaseUrl : 'https://placeholder-project.supabase.co';
const finalKey = isValidKey(supabaseAnonKey) ? supabaseAnonKey : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid';

export const supabase = createClient(finalUrl, finalKey, {
