        </div>
      </main>

      {/* Floating KING button exactly as shown in screenshots */}
      <button className="fixed bottom-10 right-10 w-16 h-16 bg-slate-950 text-amber-500 rounded-full shadow-2xl flex items-center justify-center border-4 border-slate-800 font-black text-[10px] tracking-tighter z-[101] hover:scale-110 active:scale-95 transition-all">
