                    value={broadcastMsg}
                    onChange={e => setBroadcastMsg(e.target.value)}
                  />
                  <div className="mt-8 flex justify-end">
                    <button 
                      onClick={() => {
                        customers.forEach(c => {
                          if (c.phone) {
                            const url = `https://wa.me/${c.phone.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                            window.open(url, '_blank');
                          }
                        });
                      }}
                      className="bg-emerald-500 text-white px-10 py-5 rounded-full font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-100 hover:scale-105 active:scale-95 transition-all"
                    >
                      Broadcast to All ({customers.length})
                    </button>
                  </div>
                </div>

                <div className="mt-12">
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Individual Targeting</p>
                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {customers.map(c => (
                        <div key={c.id} className="bg-white p-6 rounded-2xl border border-slate-100 flex justify-between items-center shadow-sm">
                          <div>
                            <p className="font-bold text-slate-900">{c.name}</p>
                            <p className="text-xs text-slate-400 font-medium">{c.phone || 'No Phone'}</p>
                          </div>
                          <button 
                            disabled={!c.phone}
                            onClick={() => {
                              const url = `https://wa.me/${c.phone!.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                              window.open(url, '_blank');
                            }}
                            className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                          >
                            →
                          </button>
                        </div>
                      ))}
                   </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Floating KING button exactly as shown in screenshots */}
      <button className="fixed bottom-10 right-10 w-16 h-16 bg-slate-950 text-amber-500 rounded-full shadow-2xl flex items-center justify-center border-4 border-slate-800 font-black text-[10px] tracking-tighter z-[101] hover:scale-110 active:scale-95 transition-all">
        KING
      </button>
    </div>
  );
};

export default AdminDashboard;

import { createClient } from '@supabase/supabase-js';

// Access variables via dot notation to ensure Vite's 'define' replacement works correctly
const supabaseUrl = (process.env.SUPABASE_DATABASE_URL || "").trim();
const supabaseAnonKey = (process.env.SUPABASE_ANON_KEY || "").trim();

const isValidUrl = (url: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key: string) => key && key.length > 20 && !key.includes('placeholder');

// Simulation mode check
export const isSupabaseConfigured = isValidUrl(supabaseUrl) && isValidKey(supabaseAnonKey);

if (!isSupabaseConfigured) {
  console.warn("⚠️ Be the Light: Supabase connection missing. Running in local simulation mode.");
} else {
  console.log("🚀 Be the Light: Supabase connected to " + supabaseUrl.substring(0, 25) + "...");
}

const finalUrl = isSupabaseConfigured ? supabaseUrl : 'https://placeholder.supabase.co';
const finalKey = isSupabaseConfigured ? supabaseAnonKey : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid';

export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase, isSupabaseConfigured } from '../services/supabase';

// Completed AdminDashboard component with full view rendering logic
const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    if (isSupabaseConfigured) fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!isSupabaseConfigured) {
      alert("CONFIGURATION MISSING: The app is currently in Simulation Mode. Please configure your SUPABASE_DATABASE_URL and SUPABASE_ANON_KEY env variables to enable live storage uploads.");
      return;
    }

    setUploading(true);

    try {
      const timestamp = Date.now();
      const cleanFileName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
      const filePath = `products/${timestamp}_${cleanFileName}`;

      // Upload to 'product-images' bucket
      const { data, error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: true,
          contentType: file.type 
        });

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));

    } catch (err: any) {
      console.error("Upload Detailed Error:", err);

      if (err.message === 'Failed to fetch' || (err.stack && err.stack.includes('fetch'))) {
        alert(
          "ACTION REQUIRED: RESOLVE CORS ERROR\n\n" +
          "Your browser is blocking the upload. Please apply these settings in your Supabase Dashboard:\n\n" +
          "1. Go to 'Storage' -> 'Settings'.\n" +
          "2. Under 'CORS Configuration', add a new rule.\n" +
          "3. Allowed Origins: set to '*' (for testing) or your domain.\n" +
          "4. Allowed Methods: Select GET, POST, PUT, DELETE, OPTIONS.\n" +
          "5. Allowed Headers: set to '*' or 'authorization, x-client-info, apikey, content-type'.\n" +
          "6. Save and refresh this page."
        );
      } else {
        alert('Upload Failed: ' + err.message + "\n\nTip: Ensure the bucket 'product-images' exists in your Supabase Storage.");
      }
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) {
      const existingProduct = products.find(p => p.id === editId);
      await updateProduct({ 
        ...productForm, 
        id: editId, 
        createdAt: existingProduct ? existingProduct.createdAt : Date.now() 
      });
    } else {
      await addProduct(productForm);
    }
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const lowStockCount = products.filter(p => p.stock < 5).length;
  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);

  return (
    <div className="fixed inset-0 flex bg-[#f1f4f6] font-sans text-slate-800">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-100 flex flex-col h-full shrink-0">
        <div className="h-20 flex items-center px-8 border-b border-slate-50">
          <span className="font-black text-xl tracking-tighter text-slate-900 uppercase">ARCHITECT<span className="text-amber-500">.</span></span>
        </div>

        <nav className="flex-grow py-8 px-4 space-y-2">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button
              key={view}
              onClick={() => { setActiveView(view as any); setIsEditing(false); }}
              className={`w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold transition-all ${
                activeView === view ? 'bg-amber-50 text-amber-600' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span className="capitalize">{view}</span>
            </button>
          ))}

          <div className="pt-8 pb-4">
            <span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Admin Actions</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
          </button>
        </nav>
      </aside>

      {/* Main Content Area */}
      <main className="flex-grow overflow-y-auto p-12">
        {activeView === 'Dashboard' && (
          <div className="space-y-12">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Total Revenue</p>
                   <h4 className="text-3xl font-black text-slate-900">{CURRENCY} {totalRevenue.toLocaleString()}</h4>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Total Products</p>
                   <h4 className="text-3xl font-black text-slate-900">{products.length}</h4>
                </div>
                <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Critical Stock</p>
                   <h4 className="text-3xl font-black text-red-500">{lowStockCount}</h4>
                </div>
             </div>

             <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                   <h3 className="font-black uppercase tracking-widest text-sm">Recent Clients</h3>
                </div>
                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr>
                            <th className="px-8 py-4">Client</th>
                            <th className="px-8 py-4">Location</th>
                            <th className="px-8 py-4">Investment</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {customers.map(c => (
                            <tr key={c.id} className="text-sm">
                               <td className="px-8 py-4 font-bold">{c.name}</td>
                               <td className="px-8 py-4 text-slate-500">{c.location || 'N/A'}</td>
                               <td className="px-8 py-4 font-black">{CURRENCY} {c.totalSpent?.toLocaleString()}</td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        )}

        {/* Inventory View */}
        {activeView === 'Inventory' && (
           <div>
              <div className="flex justify-between items-center mb-12">
                 <h2 className="text-3xl font-black tracking-tighter uppercase">Inventory</h2>
                 <button 
                  onClick={() => { resetForm(); setIsEditing(true); }}
                  className="bg-slate-900 text-white px-8 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-amber-500 hover:text-slate-950 transition-all"
                 >
                   Add New Product
                 </button>
              </div>

              {isEditing ? (
                 <div className="max-w-2xl bg-white p-10 rounded-3xl border border-slate-100 shadow-xl">
                    <form onSubmit={handleSaveProduct} className="space-y-6">
                       <div className="grid grid-cols-2 gap-6">
                          <div>
                             <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Product Name</label>
                             <input required className="w-full p-4 bg-slate-50 rounded-xl border border-slate-100" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} />
                          </div>
                          <div>
                             <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Category</label>
                             <select className="w-full p-4 bg-slate-50 rounded-xl border border-slate-100" value={productForm.category} onChange={e => setProductForm({...productForm, category: e.target.value as any})}>
                                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                             </select>
                          </div>
                       </div>
                       <div className="grid grid-cols-2 gap-6">
                          <div>
                             <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Price ({CURRENCY})</label>
                             <input type="number" required className="w-full p-4 bg-slate-50 rounded-xl border border-slate-100" value={productForm.price} onChange={e => setProductForm({...productForm, price: Number(e.target.value)})} />
