import { createClient } from '@supabase/supabase-js';

// Accessing variables via dot notation for Vite compatibility
const rawUrl = (process.env.SUPABASE_DATABASE_URL || "").trim();
// Ensure the URL doesn't have a trailing slash which can cause fetch errors
const supabaseUrl = rawUrl.endsWith('/') ? rawUrl.slice(0, -1) : rawUrl;
const supabaseAnonKey = (process.env.SUPABASE_ANON_KEY || "").trim();

const isValidUrl = (url: string) => url && url.startsWith('https://') && !url.includes('placeholder');
const isValidKey = (key: string) => key && key.length > 20 && !key.includes('placeholder');

export const isSupabaseConfigured = isValidUrl(supabaseUrl) && isValidKey(supabaseAnonKey);

const finalUrl = isSupabaseConfigured ? supabaseUrl : 'https://placeholder.supabase.co';
const finalKey = isSupabaseConfigured ? supabaseAnonKey : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid';

export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product, CartItem, User, AuthState, Category, Lookbook } from '../types';
import { supabase, isSupabaseConfigured } from '../services/supabase';

interface AppContextType {
  products: Product[];
  lookbooks: Lookbook[];
  cart: CartItem[];
  auth: AuthState;
  loading: boolean;
  addToCart: (product: Product, quantity: number) => void;
  addBundleToCart: (lookbook: Lookbook) => void;
  removeFromCart: (productId: string) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  login: (email: string, pass: string) => boolean;
  logout: () => void;
  signup: (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => Promise<boolean>;
  addProduct: (product: Omit<Product, 'id' | 'createdAt'>) => Promise<void>;
  updateProduct: (product: Product) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;
  addLookbook: (lb: Omit<Lookbook, 'id'>) => Promise<void>;
  updateLookbook: (lb: Lookbook) => Promise<void>;
  deleteLookbook: (id: string) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [lookbooks, setLookbooks] = useState<Lookbook[]>([]);
  const [loading, setLoading] = useState(false);
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('btl_cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('btl_auth');
    return saved ? JSON.parse(saved) : { user: null, isAuthenticated: false };
  });

  const fetchData = async () => {
    if (!isSupabaseConfigured) return;
    setLoading(true);
    try {
      const { data: pData } = await supabase.from('products').select('*').order('createdAt', { ascending: false });
      if (pData) setProducts(pData);

      const { data: lbData } = await supabase.from('lookbooks').select('*').order('created_at', { ascending: false });
      if (lbData) {
        setLookbooks(lbData.map((item: any) => ({
          id: item.id,
          title: item.title,
          description: item.description,
          price: item.price,
          imageUrl: item.image_url, // Map from image_url (schema) to imageUrl (type)
          productIds: item.product_ids || [] // Map from product_ids (schema) to productIds (type)
        })));
      }
    } catch (e) {
      console.error("Fetch failed:", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);
  useEffect(() => { localStorage.setItem('btl_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('btl_auth', JSON.stringify(auth)); }, [auth]);

  const addToCart = (product: Product, quantity: number) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        const newQty = Math.min(existing.quantity + quantity, product.stock);
        return prev.map(item => item.id === product.id ? { ...item, quantity: newQty } : item);
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const addBundleToCart = (lookbook: Lookbook) => {
    const bundleProducts = products.filter(p => lookbook.productIds.includes(p.id) && p.stock > 0);
    if (bundleProducts.length === 0) return alert("Items currently unavailable.");
    setCart(prev => {
      let newCart = [...prev];
      bundleProducts.forEach(product => {
        const existing = newCart.find(item => item.id === product.id);
        if (existing) existing.quantity = Math.min(existing.quantity + 1, product.stock);
        else newCart.push({ ...product, quantity: 1, selectedSize: 'L' });
      });
      return newCart;
    });
    alert(`Look items added to bag.`);
  };

  const addProduct = async (p: Omit<Product, 'id' | 'createdAt'>) => {
    if (!isSupabaseConfigured) return;
    try {
      const newId = `prod_${Date.now()}`;
      const payload = { ...p, id: newId, createdAt: Date.now() };
      const { data, error } = await supabase.from('products').insert([payload]).select();
      if (error) throw error;
      if (data) setProducts(prev => [data[0], ...prev]);
    } catch (e: any) {
      alert(`Product Save Failed: ${e.message}`);
    }
  };

  const updateProduct = async (p: Product) => {
    if (!isSupabaseConfigured) return;
    try {
      const { error } = await supabase.from('products').update(p).eq('id', p.id);
      if (error) throw error;
      setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    } catch (e: any) {
      alert(`Update Failed: ${e.message}`);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!isSupabaseConfigured) return;
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      setProducts(prev => prev.filter(p => p.id !== id));
    } catch (e) { console.error(e); }
  };

  const addLookbook = async (lb: Omit<Lookbook, 'id'>) => {
    if (!isSupabaseConfigured) return;
    try {
      const payload = {
        title: lb.title,
        description: lb.description,
        price: lb.price,
        image_url: lb.imageUrl, // Map to schema
        product_ids: lb.productIds // Map to schema
      };
      const { data, error } = await supabase.from('lookbooks').insert([payload]).select();
      if (error) throw error;
      if (data) {
        setLookbooks(prev => [{
          id: data[0].id,
          title: data[0].title,
          description: data[0].description,
          price: data[0].price,
          imageUrl: data[0].image_url,
          productIds: data[0].product_ids || []
        }, ...prev]);
      }
    } catch (e) { console.error(e); }
  };

  const updateLookbook = async (lb: Lookbook) => {
    if (!isSupabaseConfigured) return;
    try {
      const payload = {
        title: lb.title,
        description: lb.description,
        price: lb.price,
        image_url: lb.imageUrl,
        product_ids: lb.productIds
      };
      const { error } = await supabase.from('lookbooks').update(payload).eq('id', lb.id);
      if (error) throw error;
      setLookbooks(prev => prev.map(item => item.id === lb.id ? lb : item));
    } catch (e) { console.error(e); }
  };

  const deleteLookbook = async (id: string) => {
    if (!isSupabaseConfigured) return;
    try {
      const { error } = await supabase.from('lookbooks').delete().eq('id', id);
      if (error) throw error;
      setLookbooks(prev => prev.filter(lb => lb.id !== id));
    } catch (e) { console.error(e); }
  };

  const signup = async (email: string, pass: string, name: string, phone: string, location: string, isWhatsApp: boolean) => {
    if (!isSupabaseConfigured) return false;
    try {
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email,
        password: pass,
        options: { data: { full_name: name } }
      });
      if (authError) throw authError;
      if (authData.user) {
        const { error: profileError } = await supabase.from('profiles').upsert([{ 
          id: authData.user.id, 
          full_name: name, 
          phone, 
          location, 
          is_whatsapp: isWhatsApp // Matches schema bool column
        }]);
        if (profileError) throw profileError;
        setAuth({ user: { id: authData.user.id, email, isAdmin: false, name, phone, location, isWhatsApp }, isAuthenticated: true });
        return true;
      }
    } catch (e: any) {
      alert(`Signup Error: ${e.message}`);
      return false;
    }
    return false;
  };

  const login = (email: string, pass: string) => {
    if (email === 'admin@bethelight.com' && pass === 'admin123') {
      setAuth({ user: { id: 'admin-0', email, isAdmin: true, name: 'Admin' }, isAuthenticated: true });
      return true;
    }
    setAuth({ user: { id: 'user-0', email, isAdmin: false, name: 'Client' }, isAuthenticated: true });
    return true;
  };

  const logout = () => setAuth({ user: null, isAuthenticated: false });
  const removeFromCart = (id: string) => setCart(prev => prev.filter(i => i.id !== id));
  const updateCartQuantity = (id: string, q: number) => setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: q } : i));
  const clearCart = () => setCart([]);

  return (
    <AppContext.Provider value={{
      products, lookbooks, cart, auth, loading, addToCart, addBundleToCart, removeFromCart, updateCartQuantity, clearCart,
      login, logout, signup, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase, isSupabaseConfigured } from '../services/supabase';

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    if (isSupabaseConfigured) fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!isSupabaseConfigured) {
      alert("SUPABASE NOT CONFIGURED: Image uploads require valid SUPABASE_DATABASE_URL and SUPABASE_ANON_KEY.");
      return;
    }

    setUploading(true);

    try {
      const timestamp = Date.now();
      const cleanFileName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
      const filePath = `uploads/${timestamp}_${cleanFileName}`;

      const { data, error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: true,
          contentType: file.type 
        });

      if (uploadError) {
        // Handle specific Supabase error objects
        const errObj = (uploadError as any);
        if (errObj.status === 403 || errObj.error === 'Resource not found') {
           throw new Error("PERMISSION_DENIED: You need to add a Storage Policy to 'product-images' in Supabase.");
        }
        throw uploadError;
      }

      const { data: { publicUrl } } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));

    } catch (err: any) {
      console.error("Upload Detailed Error:", err);

      if (err.message === 'Failed to fetch') {
        alert(
          "CORS ERROR DETECTED\n\n" +
          "Your browser blocked the upload. To fix this:\n" +
          "1. Go to your Supabase Dashboard.\n" +
          "2. Navigate to Storage -> Settings -> CORS Configuration.\n" +
          "3. Add a rule with Allowed Origins: '*' and Allowed Methods: GET, POST, PUT, DELETE, OPTIONS.\n" +
          "4. Click Save."
        );
      } else if (err.message.includes('PERMISSION_DENIED')) {
        alert(
          "RLS POLICY ERROR\n\n" +
          "Bucket is 'Public', but you need an 'INSERT' policy for 'anon' or 'public' role to upload.\n" +
          "Go to Storage -> Policies -> 'product-images' and add an INSERT policy."
        );
      } else {
        alert('Upload Failed: ' + err.message);
      }
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) {
      const existingProduct = products.find(p => p.id === editId);
      await updateProduct({ 
        ...productForm, 
        id: editId, 
        createdAt: existingProduct ? existingProduct.createdAt : Date.now() 
      });
    } else {
      await addProduct(productForm);
    }
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const lowStockCount = products.filter(p => p.stock < 5).length;
  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);

  return (
    <div className="fixed inset-0 flex bg-[#f1f4f6] font-sans text-slate-800">
      <aside className="w-64 bg-white border-r border-slate-100 flex flex-col h-full shrink-0">
        <div className="h-20 flex items-center px-8 border-b border-slate-50">
          <span className="font-black text-xl tracking-tighter text-slate-900 uppercase">ARCHITECT<span className="text-amber-500">.</span></span>
        </div>
        <nav className="flex-grow py-8 px-4 space-y-2">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button key={view} onClick={() => { setActiveView(view as any); setIsEditing(false); }} className={`w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold transition-all ${activeView === view ? 'bg-amber-50 text-amber-600' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}><span className="capitalize">{view}</span></button>
          ))}
          <div className="pt-8 pb-4"><span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Admin Actions</span></div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-sm font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50"><span>← Storefront</span></button>
        </nav>
      </aside>

      <main className="flex-grow overflow-y-auto p-12">
