        <div className="h-20 flex items-center px-8 border-b border-slate-50">
          <span className="font-black text-xl tracking-tighter text-slate-900 uppercase italic">ARCHITECT<span className="text-amber-500">.</span></span>
        </div>

        <nav className="flex-grow py-8 px-4 space-y-2">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button
              key={view}
              onClick={() => { setActiveView(view as any); setIsEditing(false); }}
              className={`w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                activeView === view ? 'bg-slate-900 text-amber-500' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span>{view}</span>
            </button>
          ))}
          <div className="pt-8 pb-4">
            <span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Quick Links</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-xs font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
          </button>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-grow overflow-y-auto p-12 bg-[#f8fafc]">
        {activeView === 'Dashboard' && (
          <div className="space-y-12 animate-in fade-in duration-500">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 group hover:border-amber-500 transition-colors">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Total Revenue</p>
                   <h4 className="text-4xl font-black text-slate-900">{CURRENCY} {totalRevenue.toLocaleString()}</h4>
                </div>
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Asset Inventory</p>
                   <h4 className="text-4xl font-black text-slate-900">{products.length} Items</h4>
                </div>
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Replenishment Alert</p>
                   <h4 className={`text-4xl font-black ${lowStockCount > 0 ? 'text-red-500' : 'text-emerald-500'}`}>{lowStockCount} Critical</h4>
                </div>
             </div>

             <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
