                </div>
                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50/50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr>
                            <th className="px-8 py-5">Client Name</th>
                            <th className="px-8 py-5">Location</th>
                            <th className="px-8 py-5">Total Investment</th>
                            <th className="px-8 py-5">Tier</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {customers.map(c => (
                            <tr key={c.id} className="text-sm hover:bg-slate-50/50 transition-colors">
                               <td className="px-8 py-5 font-bold flex items-center space-x-2">
