                                   {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                             </div>
                             <div className="grid grid-cols-2 gap-6">
                                <div>
                                   <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 ml-1">Investment ({CURRENCY})</label>
