        )}

        {activeView === 'Broadcast' && (
           <div className="max-w-2xl animate-in zoom-in-95 duration-500">
              <h2 className="text-4xl font-black tracking-tighter uppercase mb-10">Maison Dispatch</h2>
              <div className="bg-white p-12 rounded-[3.5rem] border border-slate-100 shadow-2xl">
                 <p className="text-sm text-slate-500 mb-10 font-medium leading-relaxed">Broadcast a message to all registered clients via our WhatsApp integration. Each message will be initiated in a new secure session.</p>
                 <div className="relative mb-10">
                   <span className="absolute -top-3 left-6 px-3 bg-white text-[10px] font-black uppercase tracking-widest text-amber-500">Global Directive</span>
                   <textarea className="w-full p-8 bg-slate-50 rounded-[2rem] border border-slate-100 font-medium h-48 focus:bg-white transition-all outline-none" value={broadcastMsg} onChange={e => setBroadcastMsg(e.target.value)} />
                 </div>
                 <button 
                  onClick={() => {
                    const waTargets = customers.filter(c => c.phone && c.isWhatsApp);
                    if (waTargets.length === 0) {
                      alert("No valid WhatsApp targets found in the database.");
                      return;
                    }
                    waTargets.forEach((c, i) => {
                      setTimeout(() => {
                        const url = `https://wa.me/${c.phone!.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                        window.open(url, '_blank');
                      }, i * 500); // Small delay to prevent browser blocking popups
                    });
                  }}
                  className="w-full bg-slate-950 text-amber-500 py-7 rounded-2xl font-black uppercase tracking-[0.3em] hover:bg-slate-800 transition-all shadow-xl shadow-amber-500/5 active:scale-95"
                 >
                    Send to {customers.filter(c => c.phone && c.isWhatsApp).length} WhatsApp Clients
                 </button>
              </div>
           </div>
        )}
      </main>

      {/* Floating KING button */}
      <button 
        onClick={() => navigate('/')}
        className="fixed bottom-10 right-10 w-16 h-16 bg-slate-950 text-amber-500 rounded-full shadow-2xl flex items-center justify-center border-4 border-slate-800 font-black text-[10px] tracking-tighter z-[101] hover:scale-110 active:scale-95 transition-all"
      >
        KING
      </button>
