                        const url = `https://wa.me/${c.phone!.replace(/\+/g, '')}?text=${encodeURIComponent(broadcastMsg)}`;
                        window.open(url, '_blank');
                      }, i * 500); // Small delay to prevent browser blocking popups
                    });
                  }}
                  className="w-full bg-slate-950 text-amber-500 py-7 rounded-2xl font-black uppercase tracking-[0.3em] hover:bg-slate-800 transition-all shadow-xl shadow-amber-500/5 active:scale-95"
                 >
                    Send to {customers.filter(c => c.phone && c.isWhatsApp).length} WhatsApp Clients
                 </button>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

