                                   <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 ml-1">Stock Quota</label>
                                   <input type="number" required className="w-full p-5 bg-slate-50 rounded-2xl border border-slate-100 font-bold" value={productForm.stock || ''} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value) || 0})} placeholder="0" />
                                </div>
                             </div>
                          </div>
                          <div className="space-y-6">
                             <div>
                                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 ml-1">Maison Description</label>
                                <textarea className="w-full p-5 bg-slate-50 rounded-2xl border border-slate-100 h-44 font-medium resize-none" value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} placeholder="Describe the craftsmanship..." />
                             </div>
                             <div>
                                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3 ml-1">Visual Asset</label>
                                <input type="file" accept="image/*" onChange={(e) => handleImageUpload(e, 'product')} className="mb-4 text-xs" />
                                {productForm.imageUrl && <img src={productForm.imageUrl} className="w-20 h-20 object-cover rounded-2xl border shadow-lg" />}
                             </div>
                          </div>
                       </div>
                       <div className="flex gap-6 pt-10 border-t border-slate-50">
                          <button type="submit" disabled={uploading} className="flex-grow bg-slate-900 text-white py-6 rounded-2xl font-black uppercase tracking-widest hover:bg-amber-500 hover:text-slate-950 transition-all shadow-xl disabled:opacity-50">
                             {uploading ? 'Processing...' : (editId ? 'Commit Update' : 'Initialize Asset')}
                          </button>
                          <button type="button" onClick={() => setIsEditing(false)} className="px-12 border border-slate-200 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-400 bg-white">Cancel</button>
                       </div>
                    </form>
                 </div>
              ) : (
                <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50/50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr><th className="px-10 py-6">Asset</th><th className="px-10 py-6">Quota</th><th className="px-10 py-6">Investment</th><th className="px-10 py-6">Actions</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {products.map(p => (
                            <tr key={p.id} className="text-sm group">
                               <td className="px-10 py-5 flex items-center gap-6">
                                  <div className="w-12 h-12 rounded-xl overflow-hidden border border-slate-100 bg-slate-50">
                                    <img src={p.imageUrl} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                                  </div>
                                  <span className="font-black text-slate-900 uppercase tracking-tighter">{p.name}</span>
                               </td>
                               <td className={`px-10 py-5 font-black ${p.stock < 5 ? 'text-red-500' : 'text-slate-500'}`}>{p.stock}</td>
                               <td className="px-10 py-5 font-black text-lg">{CURRENCY} {p.price.toLocaleString()}</td>
                               <td className="px-10 py-5 space-x-6">
                                  <button onClick={() => {
                                    setEditId(p.id);
                                    setProductForm({ name: p.name, description: p.description, price: p.price, stock: p.stock, category: p.category, imageUrl: p.imageUrl });
                                    setIsEditing(true);
                                  }} className="text-[10px] font-black uppercase text-amber-600">Refine</button>
                                  <button onClick={() => deleteProduct(p.id)} className="text-[10px] font-black uppercase text-red-400">Remove</button>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
              )}
           </div>
        )}

        {activeView === 'Lookbooks' && (
           <div>
              <div className="flex justify-between items-center mb-12">
                 <h2 className="text-4xl font-black tracking-tighter uppercase italic">Runway Series</h2>
                 {!isEditing && <button onClick={() => { resetForm(); setIsEditing(true); }} className="bg-slate-900 text-white px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-amber-500 transition-all">Create Editorial</button>}
              </div>
              {isEditing ? (
                 <div className="max-w-3xl bg-white p-12 rounded-[3rem] border border-slate-100 shadow-xl">
                    <form onSubmit={handleSaveLookbook} className="space-y-8">
                       <div><label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3">Exhibit Title</label><input required className="w-full p-5 bg-slate-50 rounded-2xl border border-slate-100 font-bold" value={lookbookForm.title} onChange={e => setLookbookForm({...lookbookForm, title: e.target.value})} /></div>
                       <div><label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3">Narrative</label><textarea className="w-full p-5 bg-slate-50 rounded-2xl border border-slate-100 h-32 font-medium" value={lookbookForm.description} onChange={e => setLookbookForm({...lookbookForm, description: e.target.value})} /></div>
                       <div><label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3">Editorial Hero Image</label><input type="file" accept="image/*" onChange={(e) => handleImageUpload(e, 'lookbook')} className="mb-4 text-xs" /><{lookbookForm.imageUrl && <img src={lookbookForm.imageUrl} className="w-full h-48 object-cover rounded-3xl border shadow-inner" />}</div>
                       <div className="flex gap-4 pt-6"><button type="submit" disabled={uploading} className="flex-grow bg-slate-900 text-white py-6 rounded-2xl font-black uppercase tracking-widest hover:bg-amber-500 transition-all">{uploading ? 'Processing...' : (editId ? 'Update Editorial' : 'Publish to Runway')}</button><button type="button" onClick={() => setIsEditing(false)} className="px-10 border border-slate-200 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-400">Cancel</button></div>
                    </form>
                 </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                   {lookbooks.map(lb => (
                      <div key={lb.id} className="bg-white rounded-[2.5rem] overflow-hidden border border-slate-100 shadow-sm group">
                         <img src={lb.imageUrl} className="w-full h-64 object-cover grayscale transition-all duration-700 group-hover:grayscale-0" />
                         <div className="p-10"><h4 className="text-2xl font-black uppercase tracking-tighter mb-4">{lb.title}</h4><div className="flex gap-6 pt-6 border-t border-slate-50"><button onClick={() => { setEditId(lb.id); setLookbookForm({ title: lb.title, description: lb.description, price: lb.price, imageUrl: lb.imageUrl, productIds: lb.productIds }); setIsEditing(true); }} className="text-[10px] font-black uppercase text-amber-600">Refine</button><button onClick={() => deleteLookbook(lb.id)} className="text-[10px] font-black uppercase text-red-400">Decommission</button></div></div>
                      </div>
                   ))}
                </div>
              )}
           </div>
        )}

        {activeView === 'Broadcast' && (
           <div className="max-w-2xl">
              <h2 className="text-4xl font-black tracking-tighter uppercase mb-10">Maison Dispatch</h2>
              <div className="bg-white p-12 rounded-[3.5rem] border border-slate-100 shadow-2xl">
                 <p className="text-sm text-slate-500 mb-10 font-medium leading-relaxed">Broadcast a message to all registered clients via our simulation suite. This enables rapid community engagement for new collection drops.</p>
                 <textarea className="w-full p-8 bg-slate-50 rounded-[2rem] border border-slate-100 font-medium h-48 focus:bg-white transition-all outline-none" value={broadcastMsg} onChange={e => setBroadcastMsg(e.target.value)} />
                 <button className="w-full bg-slate-950 text-amber-500 py-7 rounded-2xl font-black uppercase tracking-[0.3em] hover:bg-slate-800 transition-all shadow-xl shadow-amber-500/5 mt-10 active:scale-95">Initiate Global Directive</button>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

