import React, { useState, useMemo } from 'react';
// Fix: Use namespace import to resolve missing named exports error
import * as ReactRouterDOM from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Category } from '../types';

const { Link } = ReactRouterDOM;

const Shop: React.FC = () => {
  const { products } = useApp();
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<Category | 'All'>('All');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase()) || 
                           p.description.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, selectedCategory]);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
        <div>
          <h1 className="text-4xl font-bold mb-2">Our Collection</h1>
          <p className="text-slate-500">Discover your next favorite look.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
          {/* Search */}
          <div className="relative flex-grow">
            <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-400">
              <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </span>
            <input 
              type="text" 
              placeholder="Search products..."
              className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl bg-slate-50 focus:ring-amber-500 focus:border-amber-500 text-sm"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          {/* Category Filter */}
          <select 
            className="block w-full sm:w-48 py-3 px-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-amber-500 focus:border-amber-500 text-sm"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value as any)}
          >
            <option value="All">All Categories</option>
            {CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
          </select>
        </div>
      </div>

      {filteredProducts.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-x-8 gap-y-12">
          {filteredProducts.map((product) => (
            <Link key={product.id} to={`/product/${product.id}`} className="group">
              <div className="relative aspect-[3/4] overflow-hidden rounded-2xl bg-slate-100 mb-4">
                <img 
                  src={product.imageUrl} 
                  alt={product.name}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                />
                {product.stock === 0 && (
                  <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] flex items-center justify-center">
                    <span className="bg-slate-900 text-white font-bold px-4 py-2 rounded-full text-sm">SOLD OUT</span>
                  </div>
                )}
                {product.stock > 0 && product.stock <= 3 && (
                   <div className="absolute top-4 left-4 bg-amber-500 text-white text-xs font-bold px-3 py-1 rounded-full">
                    ONLY {product.stock} LEFT
                  </div>
                )}
              </div>
              <h3 className="font-semibold text-lg group-hover:text-amber-600 transition-colors">{product.name}</h3>
              <p className="text-slate-500 text-sm mb-1">{product.category}</p>
              <div className="flex items-center justify-between">
                <p className="font-bold text-slate-900">{CURRENCY} {product.price.toFixed(2)}</p>
                {product.stock > 0 && (
                   <span className="text-xs font-semibold text-emerald-600 uppercase tracking-widest">Available</span>
                )}
              </div>
            </Link>
          ))}
        </div>
      ) : (
        <div className="text-center py-24">
          <div className="inline-block p-6 bg-slate-50 rounded-full mb-4">
            <svg className="w-12 h-12 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-slate-900">No items found</h2>
          <p className="text-slate-500 mt-2">Try adjusting your filters or search terms.</p>
        </div>
      )}
    </div>
  );
};

