import React, { useState } from 'react';
// Fix: Use namespace import to resolve missing named exports error
import * as ReactRouterDOM from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CURRENCY } from '../constants';
import { Size } from '../types';

const { useParams, Link, useNavigate } = ReactRouterDOM;

const SIZES: Size[] = ['S', 'M', 'L', 'XL', 'XXL'];

const ProductDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { products, addToCart } = useApp();
  const navigate = useNavigate();
  const [quantity, setQuantity] = useState(1);
  const [selectedSize, setSelectedSize] = useState<Size>('M');

  const product = products.find(p => p.id === id);

  if (!product) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center p-4">
        <h2 className="text-2xl font-bold mb-4">Product Not Found</h2>
        <Link to="/shop" className="text-amber-500 hover:underline font-bold">Back to Catalog</Link>
      </div>
    );
  }

  const handleAddToCart = () => {
    addToCart({ ...product, selectedSize } as any, quantity);
    navigate('/cart');
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 items-start">
        {/* Product Image Gallery */}
        <div className="relative aspect-[4/5] rounded-[3rem] overflow-hidden bg-slate-100 shadow-2xl">
          <img 
            src={product.imageUrl} 
            alt={product.name} 
            className="w-full h-full object-cover"
          />
          {product.stock === 0 && (
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center">
              <span className="text-white text-4xl font-black border-4 border-white px-10 py-5 uppercase tracking-[0.2em]">Waitlisted</span>
            </div>
          )}
        </div>

        {/* Product Info */}
        <div className="flex flex-col">
          <div className="mb-12">
            <Link to="/shop" className="text-amber-600 text-xs font-black uppercase tracking-[0.3em] mb-6 inline-block hover:text-amber-700 transition-colors">
              Collections / {product.category}
            </Link>
            <h1 className="text-5xl md:text-6xl font-black text-slate-900 mb-6 tracking-tighter leading-none">{product.name}</h1>
            <div className="flex items-center space-x-6 mb-8">
              <span className="text-4xl font-black text-slate-900">{CURRENCY} {product.price.toLocaleString()}</span>
              {product.stock > 0 && (
                <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-4 py-2 rounded-full uppercase tracking-widest border border-emerald-100">
                  Ready to ship
                </span>
              )}
            </div>
            <p className="text-xl text-slate-500 leading-relaxed font-medium">
              {product.description}
            </p>
          </div>

          {product.stock > 0 ? (
            <div className="space-y-12">
              {/* Size Selector */}
              <div>
                <div className="flex justify-between items-center mb-6">
                  <span className="text-sm font-black uppercase tracking-widest text-slate-400">Select Size (US)</span>
                  <button className="text-[10px] font-black uppercase tracking-widest text-amber-600 underline">Size Guide</button>
                </div>
                <div className="flex flex-wrap gap-4">
                  {SIZES.map(size => (
                    <button 
                      key={size}
                      onClick={() => setSelectedSize(size)}
                      className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-lg transition-all border-2 ${selectedSize === size ? 'border-slate-900 bg-slate-900 text-white shadow-xl shadow-slate-200' : 'border-slate-100 text-slate-400 hover:border-amber-500'}`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex items-center space-x-8">
                <div className="flex items-center border-2 border-slate-100 rounded-3xl overflow-hidden px-2">
                  <button 
                    onClick={() => setQuantity(q => Math.max(1, q - 1))}
                    className="w-12 h-16 flex items-center justify-center text-slate-400 hover:text-slate-900"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                  </button>
                  <span className="w-10 text-center font-black text-xl">{quantity}</span>
                  <button 
                    onClick={() => setQuantity(q => Math.min(product.stock, q + 1))}
                    className="w-12 h-16 flex items-center justify-center text-slate-400 hover:text-slate-900"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                  </button>
                </div>

                <button 
                  onClick={handleAddToCart}
                  className="flex-grow bg-slate-900 text-white py-6 rounded-3xl font-black text-xs uppercase tracking-[0.2em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-2xl active:scale-[0.98]"
                >
                  Acquire Item
                </button>
              </div>
            </div>
          ) : (
            <button disabled className="w-full bg-slate-100 text-slate-400 py-6 rounded-3xl font-black text-xs uppercase tracking-widest cursor-not-allowed">
              Out of Stock
            </button>
          )}

          {/* Reviews Preview */}
          <div className="mt-20 pt-12 border-t border-slate-100">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">Customer Reviews</h3>
