import React, { useState, useEffect } from 'react';
// Fix: Use namespace import to resolve missing named exports error
import * as ReactRouterDOM from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase, isSupabaseConfigured } from '../services/supabase';

const { useNavigate } = ReactRouterDOM;

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('New Arrivals have landed at Be the Light! Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    if (isSupabaseConfigured) fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!isSupabaseConfigured) {
      alert("Storage is in Simulation Mode. Configure keys to enable live uploads.");
      return;
    }

    setUploading(true);

    try {
      const timestamp = Date.now();
      const cleanFileName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
      const filePath = `uploads/${timestamp}_${cleanFileName}`;

      const { data, error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: true,
          contentType: file.type 
        });

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));

    } catch (err: any) {
      console.error("Upload Detailed Error:", err);
      alert('Upload Failed: ' + err.message);
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) {
      const existingProduct = products.find(p => p.id === editId);
      await updateProduct({ 
        ...productForm, 
        id: editId, 
        createdAt: existingProduct ? existingProduct.createdAt : Date.now() 
      });
    } else {
      await addProduct(productForm);
    }
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const lowStockCount = products.filter(p => p.stock < 5).length;
  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);

  return (
    <div className="fixed inset-0 flex bg-[#f1f4f6] font-sans text-slate-800">
      <aside className="w-64 bg-white border-r border-slate-100 flex flex-col h-full shrink-0 shadow-sm">
        <div className="h-20 flex items-center px-8 border-b border-slate-50">
          <span className="font-black text-xl tracking-tighter text-slate-900 uppercase italic">ARCHITECT<span className="text-amber-500">.</span></span>
        </div>

        <nav className="flex-grow py-8 px-4 space-y-2">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button
              key={view}
              onClick={() => { setActiveView(view as any); setIsEditing(false); }}
              className={`w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                activeView === view ? 'bg-slate-900 text-amber-500' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span>{view}</span>
            </button>
          ))}
          <div className="pt-8 pb-4">
            <span className="px-5 text-[10px] font-black uppercase tracking-widest text-slate-300">Quick Links</span>
          </div>
          <button onClick={() => navigate('/')} className="w-full flex items-center space-x-4 px-5 py-3.5 rounded-xl text-xs font-bold text-slate-400 hover:text-slate-900 hover:bg-slate-50">
            <span>← Storefront</span>
          </button>
        </nav>
      </aside>

      <main className="flex-grow overflow-y-auto p-12 bg-[#f8fafc]">
        {activeView === 'Dashboard' && (
          <div className="space-y-12">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 group hover:border-amber-500 transition-colors">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Total Revenue</p>
                   <h4 className="text-4xl font-black text-slate-900">{CURRENCY} {totalRevenue.toLocaleString()}</h4>
                </div>
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Asset Inventory</p>
                   <h4 className="text-4xl font-black text-slate-900">{products.length} Items</h4>
                </div>
                <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4">Critical Stock</p>
                   <h4 className={`text-4xl font-black ${lowStockCount > 0 ? 'text-red-500' : 'text-emerald-500'}`}>{lowStockCount} Critical</h4>
                </div>
             </div>
             <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                   <h3 className="font-black uppercase tracking-widest text-xs text-slate-500">Recent Clients</h3>
                </div>
                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50/50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr><th className="px-8 py-5">Client Name</th><th className="px-8 py-5">Location</th><th className="px-8 py-5">Investment</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {customers.map(c => (
                            <tr key={c.id} className="text-sm hover:bg-slate-50/50 transition-colors">
                               <td className="px-8 py-5 font-bold">{c.name}</td>
                               <td className="px-8 py-5 text-slate-500 font-medium">{c.location || 'Pending...'}</td>
                               <td className="px-8 py-5 font-black">{CURRENCY} {c.totalSpent?.toLocaleString()}</td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        )}

        {activeView === 'Inventory' && (
           <div>
              <div className="flex justify-between items-center mb-12">
                 <h2 className="text-4xl font-black tracking-tighter uppercase">Inventory Core</h2>
                 {!isEditing && (
                   <button 
                    onClick={() => { resetForm(); setIsEditing(true); }}
                    className="bg-slate-900 text-white px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-xl active:scale-95"
