                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="admin@bethelight.com"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Security Key</label>
