                className="w-full px-5 py-4 rounded-xl bg-slate-800 border border-slate-700 text-white focus:ring-2 focus:ring-amber-500 focus:border-transparent transition-all outline-none"
                value={pass}
                onChange={e => setPass(e.target.value)}
                placeholder="••••••••"
              />
            </div>

            <button 
              type="submit" 
              className="w-full bg-amber-500 text-slate-950 py-4 rounded-xl font-black uppercase tracking-widest hover:bg-amber-400 transition-all shadow-lg shadow-amber-500/20 active:scale-[0.98]"
            >
              Enter Management Suite
            </button>
          </form>
        </div>

        <div className="mt-8 text-center">
          <button 
            onClick={() => navigate('/')} 
