import React, { useState, useEffect } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
import { useApp } from '../store/AppContext';
import { CATEGORIES, CURRENCY } from '../constants';
import { Product, User, Lookbook } from '../types';
import { supabase, isSupabaseConfigured } from '../services/supabase';

const { useNavigate } = ReactRouterDOM;

const AdminDashboard: React.FC = () => {
  const { products, lookbooks, addProduct, updateProduct, deleteProduct, addLookbook, updateLookbook, deleteLookbook, auth } = useApp();
  const navigate = useNavigate();

  const [activeView, setActiveView] = useState<'Dashboard' | 'Inventory' | 'Lookbooks' | 'Broadcast'>('Dashboard');
  const [customers, setCustomers] = useState<User[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [broadcastMsg, setBroadcastMsg] = useState('Greetings from Be the Light. Our new luxury collection has arrived. Visit us at Aflao, 2 Lowcost.');

  const [productForm, setProductForm] = useState({ 
    name: '', 
    description: '', 
    price: 0, 
    stock: 0, 
    category: CATEGORIES[0], 
    imageUrl: '' 
  });

  const [lookbookForm, setLookbookForm] = useState({ 
    title: '', 
    description: '', 
    price: 0, 
    imageUrl: '', 
    productIds: [] as string[] 
  });

  useEffect(() => {
    if (!auth.user?.isAdmin) navigate('/admin-portal');
    if (isSupabaseConfigured) fetchCustomers();
  }, [auth, navigate]);

  const fetchCustomers = async () => {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) {
        setCustomers(data.map((p: any) => ({
          id: p.id,
          name: p.full_name || 'Anonymous',
          email: 'client@example.com',
          isAdmin: false,
          phone: p.phone,
          location: p.location,
          totalSpent: p.total_spent || 0,
          orderCount: p.orders_count || 0
        })));
      }
    } catch (e) {
      console.error("Failed to fetch profiles", e);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'lookbook') => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!isSupabaseConfigured) return alert("Storage restricted. Configure keys.");
    setUploading(true);
    try {
      const timestamp = Date.now();
      const filePath = `uploads/${timestamp}_${file.name.replace(/[^a-zA-Z0-9.]/g, '_')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data: { publicUrl } } = supabase.storage.from('product-images').getPublicUrl(filePath);
      if (type === 'product') setProductForm(p => ({ ...p, imageUrl: publicUrl }));
      else setLookbookForm(l => ({ ...l, imageUrl: publicUrl }));
    } catch (err: any) {
      alert('Upload Failed: ' + err.message);
    } finally { setUploading(false); }
  };

  const resetForm = () => {
    setIsEditing(false);
    setEditId(null);
    setProductForm({ name: '', description: '', price: 0, stock: 0, category: CATEGORIES[0], imageUrl: '' });
    setLookbookForm({ title: '', description: '', price: 0, imageUrl: '', productIds: [] });
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateProduct({ ...productForm, id: editId, createdAt: Date.now() });
    else await addProduct(productForm);
    resetForm();
  };

  const handleSaveLookbook = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editId) await updateLookbook({ ...lookbookForm, id: editId });
    else await addLookbook(lookbookForm);
    resetForm();
  };

  const totalRevenue = customers.reduce((acc, c) => acc + (c.totalSpent || 0), 0);
  const lowStock = products.filter(p => p.stock < 5).length;

  return (
    <div className="fixed inset-0 flex bg-[#f8fafc] font-sans text-slate-900">
      {/* Sidebar - Architectural Design */}
      <aside className="w-72 bg-white border-r border-slate-100 flex flex-col h-full shrink-0 shadow-2xl z-50">
        <div className="h-24 flex items-center px-10 border-b border-slate-50">
          <span className="font-black text-2xl tracking-tighter text-slate-950 uppercase italic">MAISON<span className="text-amber-500">.</span>CORE</span>
        </div>
        <nav className="flex-grow py-12 px-6 space-y-3">
          {['Dashboard', 'Inventory', 'Lookbooks', 'Broadcast'].map((view) => (
            <button
              key={view}
              onClick={() => { setActiveView(view as any); setIsEditing(false); }}
              className={`w-full flex items-center px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] transition-all ${
                activeView === view ? 'bg-slate-950 text-amber-500 shadow-xl' : 'text-slate-400 hover:text-slate-950 hover:bg-slate-50'
              }`}
            >
              {view}
            </button>
          ))}
        </nav>
        <div className="p-8 border-t border-slate-50">
           <button onClick={() => navigate('/')} className="w-full text-center text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-950 transition-colors">← Exit Workspace</button>
        </div>
      </aside>

      {/* Workspace */}
      <main className="flex-grow overflow-y-auto p-16 bg-[#fcfdfe]">
        {activeView === 'Dashboard' && (
          <div className="space-y-16 animate-in fade-in duration-700">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 group hover:border-amber-500 transition-all duration-500">
                   <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6">Total Asset Value</p>
                   <h4 className="text-5xl font-black text-slate-950 tracking-tighter">{CURRENCY} {totalRevenue.toLocaleString()}</h4>
                </div>
                <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6">Active Inventory</p>
                   <h4 className="text-5xl font-black text-slate-950 tracking-tighter">{products.length} Units</h4>
                </div>
                <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
                   <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-6">Fulfillment Health</p>
                   <h4 className={`text-5xl font-black tracking-tighter ${lowStock > 0 ? 'text-red-500' : 'text-emerald-500'}`}>{lowStock} Critical</h4>
                </div>
             </div>

             <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden">
                <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                   <h3 className="font-black uppercase tracking-widest text-xs text-slate-400">Elite Client Relations</h3>
                </div>
                <table className="w-full text-left">
                   <thead className="bg-slate-50/30 text-[10px] font-black uppercase tracking-widest text-slate-400">
                      <tr><th className="px-10 py-6">Client Identity</th><th className="px-10 py-6">Operational Location</th><th className="px-10 py-6">Gross Investment</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-50">
                      {customers.map(c => (
                         <tr key={c.id} className="text-sm hover:bg-slate-50/50 transition-colors">
                            <td className="px-10 py-7 font-black text-slate-950 uppercase tracking-tighter">{c.name}</td>
                            <td className="px-10 py-7 text-slate-500 font-medium italic">{c.location || 'Stationary'}</td>
                            <td className="px-10 py-7 font-black text-lg">{CURRENCY} {c.totalSpent?.toLocaleString()}</td>
                         </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        )}

        {activeView === 'Inventory' && (
           <div className="animate-in slide-in-from-bottom-8 duration-700">
              <div className="flex justify-between items-center mb-16">
                 <h2 className="text-5xl font-black tracking-tighter uppercase italic">Inventory Assets</h2>
                 {!isEditing && <button onClick={() => { resetForm(); setIsEditing(true); }} className="bg-slate-950 text-white px-12 py-6 rounded-3xl font-black text-[11px] uppercase tracking-[0.4em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-2xl">+ New Acquisition</button>}
              </div>

              {isEditing ? (
                 <div className="max-w-4xl bg-white p-16 rounded-[4rem] border border-slate-100 shadow-2xl">
                    <form onSubmit={handleSaveProduct} className="space-y-12">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                          <div className="space-y-8">
                             <div>
                                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Asset Identifier</label>
                                <input required className="w-full p-6 bg-slate-50 rounded-2xl border border-slate-100 font-black focus:bg-white transition-all outline-none" value={productForm.name} onChange={e => setProductForm({...productForm, name: e.target.value})} placeholder="e.g. MONARCH SILK SHIRT" />
                             </div>
                             <div className="grid grid-cols-2 gap-8">
                                <div>
                                   <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Investment ({CURRENCY})</label>
                                   <input type="number" step="0.01" required className="w-full p-6 bg-slate-50 rounded-2xl border border-slate-100 font-black" value={productForm.price || ''} onChange={e => setProductForm({...productForm, price: parseFloat(e.target.value) || 0})} />
                                </div>
                                <div>
                                   <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Quota</label>
                                   <input type="number" required className="w-full p-6 bg-slate-50 rounded-2xl border border-slate-100 font-black" value={productForm.stock || ''} onChange={e => setProductForm({...productForm, stock: parseInt(e.target.value) || 0})} />
                                </div>
                             </div>
                          </div>
                          <div className="space-y-8">
                             <div>
                                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Maison Narrative</label>
                                <textarea className="w-full p-6 bg-slate-50 rounded-2xl border border-slate-100 h-40 font-medium resize-none" value={productForm.description} onChange={e => setProductForm({...productForm, description: e.target.value})} placeholder="Describe the silhouette and heritage..." />
                             </div>
                          </div>
                       </div>
                       <div className="flex gap-8 pt-12 border-t border-slate-50">
                          <button type="submit" disabled={uploading} className="flex-grow bg-slate-950 text-white py-7 rounded-3xl font-black uppercase tracking-[0.4em] hover:bg-amber-500 hover:text-slate-950 transition-all shadow-2xl disabled:opacity-50">
                             {uploading ? 'Finalizing...' : (editId ? 'Commit Changes' : 'Initialize Asset')}
                          </button>
                          <button type="button" onClick={() => setIsEditing(false)} className="px-16 border border-slate-200 rounded-3xl font-black text-[11px] uppercase tracking-widest text-slate-400 bg-white">Cancel</button>
                       </div>
                    </form>
                 </div>
              ) : (
                <div className="bg-white rounded-[3.5rem] border border-slate-100 overflow-hidden shadow-sm">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50/30 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr><th className="px-12 py-8">Identity</th><th className="px-12 py-8">Fulfillment Quota</th><th className="px-12 py-8">Valuation</th><th className="px-12 py-8">Operations</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {products.map(p => (
                            <tr key={p.id} className="text-sm group hover:bg-slate-50 transition-colors">
                               <td className="px-12 py-8 flex items-center gap-8">
                                  <div className="w-16 h-16 rounded-[1.5rem] overflow-hidden border border-slate-100 bg-slate-100 shadow-inner">
                                    <img src={p.imageUrl} className="w-full h-full object-cover grayscale transition-all duration-700 group-hover:grayscale-0" />
                                  </div>
                                  <span className="font-black text-slate-950 uppercase tracking-tighter text-lg">{p.name}</span>
                               </td>
                               <td className={`px-12 py-8 font-black ${p.stock < 5 ? 'text-red-500 underline' : 'text-slate-500'}`}>{p.stock} Units</td>
                               <td className="px-12 py-8 font-black text-xl">{CURRENCY} {p.price.toLocaleString()}</td>
                               <td className="px-12 py-8 space-x-8">
                                  <button onClick={() => { setEditId(p.id); setProductForm({ ...p }); setIsEditing(true); }} className="text-[10px] font-black uppercase text-amber-600 hover:text-amber-800 tracking-widest transition-colors">Refine</button>
                                  <button onClick={() => deleteProduct(p.id)} className="text-[10px] font-black uppercase text-red-400 hover:text-red-600 tracking-widest transition-colors">Decommission</button>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
              )}
           </div>
        )}

        {activeView === 'Broadcast' && (
           <div className="max-w-3xl animate-in zoom-in-95 duration-700">
              <h2 className="text-5xl font-black tracking-tighter uppercase mb-16 italic">Maison Dispatch</h2>
              <div className="bg-white p-16 rounded-[4rem] border border-slate-100 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.12)]">
                 <p className="text-lg text-slate-500 mb-12 font-medium leading-relaxed italic">Global directive system enabled. Registered clientele will receive these encrypted communications via secure simulation suites.</p>
                 <div className="relative">
                   <span className="absolute -top-4 left-10 px-5 bg-white text-[10px] font-black uppercase tracking-[0.5em] text-amber-500">Maison Frequency</span>
                   <textarea className="w-full p-10 bg-slate-50 rounded-[3rem] border border-slate-100 font-medium h-60 focus:bg-white transition-all outline-none text-lg leading-relaxed shadow-inner" value={broadcastMsg} onChange={e => setBroadcastMsg(e.target.value)} />
                 </div>
                 <button className="w-full bg-slate-950 text-amber-500 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.5em] hover:bg-slate-800 transition-all shadow-2xl mt-12 active:scale-[0.98] text-sm">Initiate Global Directive</button>
              </div>
           </div>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;

